'use strict';

/**
 * Persistence layer for Space Fractions.
 *
 * Owns the connection pool, migration/seed application, and the transactional
 * operations required by the acceptance contract (space-fractions.md 41-49):
 *
 *   * PostgreSQL is the system of record for all game state.
 *   * A verified OIDC subject string maps to a numeric internal user id via an
 *     idempotent, concurrency-safe upsert.
 *   * Score updates serialize per game and deduplicate repeated question answers
 *     within the same transaction.
 *   * A single owned transaction client is used per operation and rolled back on
 *     any error.
 *
 * PG16 constraint: we never use EXCLUDED inside a RETURNING clause (illegal on
 * PG16). Every upsert uses a simple `INSERT ... ON CONFLICT (...) DO UPDATE ...
 * RETURNING` statement instead of elaborate CTEs.
 */

const fs = require('node:fs');
const path = require('node:path');
const { Pool } = require('pg');

const { parseFraction, equals } = require('./fraction');
const { States, initialState } = require('./game-state');

const SQL_DIR = path.join(__dirname, '..', 'sql');
const MIGRATION_DIR = path.join(SQL_DIR, 'migrations');

/**
 * Minimal error type for persistence-layer failures so callers can map them to
 * HTTP statuses without coupling to pg error codes.
 */
class DbError extends Error {
  constructor(message, code) {
    super(message);
    this.name = 'DbError';
    this.code = code || 'DB_ERROR';
  }
}

/**
 * Build a Pool from a config object (or a pg ConnectionConfig string).
 * Accepts a config with a `connectionString` or individual host/db/user keys.
 */
function createPool(config) {
  if (typeof config === 'string') {
    return new Pool({ connectionString: config });
  }
  if (config && typeof config === 'object') {
    return new Pool(config);
  }
  return new Pool();
}

/**
 * Apply the canonical migration (sql/migrations/001_init.sql) idempotently.
 * The migration itself uses `\i ../game_ddl.sql` plus seed inserts with
 * ON CONFLICT DO NOTHING, so running it more than once is a no-op. Because the
 * `\i` psql meta-command is not valid inside a single pg query, we execute the
 * files in dependency order here: game_ddl.sql first, then the seed body of
 * 001_init.sql.
 *
 * Returns the list of files applied.
 */
async function migrate(poolOrClient) {
  const client =
    typeof poolOrClient.query === 'function' && typeof poolOrClient.connect === 'function'
      ? await poolOrClient.connect()
      : poolOrClient;
  const owned = client !== poolOrClient;

  let ddl;
  let migration;
  try {
    ddl = fs.readFileSync(path.join(SQL_DIR, 'game_ddl.sql'), 'utf8');
    migration = fs.readFileSync(path.join(MIGRATION_DIR, '001_init.sql'), 'utf8');
  } catch (err) {
    if (owned) client.release();
    throw new DbError(`Failed to read SQL migration files: ${err.message}`, 'MIGRATION_READ_ERROR');
  }

  const applied = [];
  try {
    await client.query(ddl);
    applied.push('game_ddl.sql');

    // Strip the psql `\i` include line; the schema has already been applied above.
    const seedBody = migration
      .split(/\r?\n/)
      .filter((line) => !/^\\i\s/.test(line.trim()))
      .join('\n');

    await client.query(seedBody);
    applied.push('001_init.sql');
  } catch (err) {
    throw new DbError(`Migration failed: ${err.message}`, 'MIGRATION_ERROR');
  } finally {
    if (owned) client.release();
  }

  return applied;
}

/**
 * Upsert a verified OIDC subject and return its numeric internal user id.
 * Because users.sub is UNIQUE, concurrent calls for the same subject converge
 * to the same row id deterministically (no races, no duplicates).
 */
async function upsertUser(client, sub, displayName = '') {
  const result = await client.query(
    `INSERT INTO users (sub, display_name)
     VALUES ($1, $2)
     ON CONFLICT (sub) DO UPDATE SET display_name = EXCLUDED.display_name
     RETURNING id`,
    [sub, displayName]
  );
  return result.rows[0].id;
}

/**
 * Run `fn` inside a single owned transaction client. `fn(client)` receives the
 * transaction client and its return value is committed. On any error, the
 * transaction is rolled back and the client released before the error propagates.
 */
async function withTransaction(pool, fn) {
  const client = await pool.connect();
  let released = false;
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch (_rollbackErr) {
      /* best-effort rollback only */
    }
    throw err;
  } finally {
    client.release();
    released = true;
    void released;
  }
}

/**
 * Create a new game owned by `ownerUserId`. `questionIds` is an optional array;
 * when empty/undefined, draw from the seeded question bank in deterministic id
 * order. Persists the game row (game_state JSONB seeded with the Playing state)
 * and the stable, position-ordered question set in one transaction.
 *
 * Returns { id, questions } where questions is [{ id, prompt, options }] with no
 * correctAnswer (contract: never leak answers to players).
 */
async function createGame(pool, ownerUserId, questionIds) {
  return withTransaction(pool, async (client) => {
    const { rows } = await client.query(
      `INSERT INTO games (game_state) VALUES ($1) RETURNING id`,
      [JSON.stringify(initialState())]
    );
    const gameId = rows[0].id;

    await client.query(
      `INSERT INTO games_owners (game_id, owner_user_id) VALUES ($1, $2)`,
      [gameId, ownerUserId]
    );

    // Select the question set: explicit ids if provided, otherwise the seeded set.
    let questionRows;
    if (Array.isArray(questionIds) && questionIds.length > 0) {
      questionRows = await client.query(
        `SELECT id, prompt, options FROM questions WHERE id = ANY($1::int[]) ORDER BY id`,
        [questionIds]
      );
    } else {
      questionRows = await client.query(
        `SELECT id, prompt, options FROM questions ORDER BY id`
      );
    }

    const ordered = questionRows.rows;
    for (let i = 0; i < ordered.length; i += 1) {
      await client.query(
        `INSERT INTO game_questions (game_id, question_id, position) VALUES ($1, $2, $3)`,
        [gameId, ordered[i].id, i]
      );
    }

    return {
      id: gameId,
      questions: ordered.map((q) => ({
        id: q.id,
        prompt: q.prompt,
        options: q.options,
      })),
    };
  });
}

/**
 * Load a game's persisted state (id, owner sub mapping, state, score) without
 * leaking answer keys. Returns null when the game does not exist, or a sentinel
 * { exists:false, ownerUserId:null } shape so callers can distinguish 404 vs
 * 403 (other user's game).
 */
async function getGame(pool, gameId) {
  const result = await pool.query(
    `SELECT g.id, g.game_state, o.owner_user_id
       FROM games g
       LEFT JOIN games_owners o ON o.game_id = g.id
      WHERE g.id = $1`,
    [gameId]
  );
  if (result.rows.length === 0) {
    return null;
  }
  const row = result.rows[0];
  const state = typeof row.game_state === 'string' ? JSON.parse(row.game_state) : row.game_state;
  return {
    id: row.id,
    ownerUserId: row.owner_user_id,
    state: state && state.state ? state.state : States.PLAYING,
    score: state && typeof state.score === 'number' ? state.score : 0,
  };
}

/**
 * Submit an answer for `gameId`/`questionId` within a single serialized
 * transaction. Enforces:
 *
 *   * Ownership check (other user's game -> typed 403 error).
 *   * The game must be Playing to accept an answer (paused/finished -> 409).
 *   * `answer` must parse as a single reduced fraction; malformed -> 400.
 *   * A repeated answer for the same question does NOT increase the score and
 *     returns the existing result (idempotent 200) rather than a 409.
 *
 * The per-game lock (SELECT ... FOR UPDATE) serializes concurrent score updates.
 * The unique index on answers(game_id, question_id) plus the transaction makes
 * deduplication safe.
 */
async function submitAnswer(pool, gameId, questionId, answer, ownerUserId) {
  return withTransaction(pool, async (client) => {
    // Lock the game row to serialize score updates for this game.
    const gameResult = await client.query(
      `SELECT game_state FROM games WHERE id = $1 FOR UPDATE`,
      [gameId]
    );
    if (gameResult.rows.length === 0) {
      const err = new DbError('Game not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }

    const ownerResult = await client.query(
      `SELECT owner_user_id FROM games_owners WHERE game_id = $1`,
      [gameId]
    );
    const actualOwner = ownerResult.rows.length ? ownerResult.rows[0].owner_user_id : null;
    if (actualOwner === null || actualOwner !== ownerUserId) {
      const err = new DbError('Not authorized for this game', 'FORBIDDEN');
      err.status = 403;
      throw err;
    }

    const gameState =
      typeof gameResult.rows[0].game_state === 'string'
        ? JSON.parse(gameResult.rows[0].game_state)
        : gameResult.rows[0].game_state;
    const currentState = gameState && gameState.state ? gameState.state : States.PLAYING;
    if (currentState !== States.PLAYING) {
      const err = new DbError(`Game is not playable (${currentState})`, 'CONFLICT');
      err.status = 409;
      throw err;
    }

    // Validate the submitted answer as a single reduced fraction (server-side).
    let submitted;
    try {
      submitted = parseFraction(answer);
    } catch (fractionErr) {
      const err = new DbError(fractionErr.message, 'INVALID_FRACTION');
      err.status = 400;
      throw err;
    }

    // Fetch the question and its canonical correct answer.
    const questionResult = await client.query(
      `SELECT correct_answer FROM questions WHERE id = $1`,
      [questionId]
    );
    if (questionResult.rows.length === 0) {
      const err = new DbError('Question not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }
    const correctAnswerText = questionResult.rows[0].correct_answer;
    let correct;
    try {
      const correctFraction = parseFraction(correctAnswerText);
      correct = equals(submitted, correctFraction);
    } catch (_e) {
      correct = false;
    }

    // Deduplicate: if this question was already answered, return the stored
    // result without changing the score.
    const existing = await client.query(
      `SELECT correct FROM answers WHERE game_id = $1 AND question_id = $2`,
      [gameId, questionId]
    );
    if (existing.rows.length > 0) {
      const wasCorrect = existing.rows[0].correct;
      const score = await computeScore(client, gameId);
      return { correct: wasCorrect, score };
    }

    // Record the answer.
    await client.query(
      `INSERT INTO answers (game_id, question_id, answer, correct)
       VALUES ($1, $2, $3, $4)`,
      [gameId, questionId, String(answer), correct]
    );

    // Increment the persisted score only when correct (each correct = 1).
    if (correct) {
      const currentScore =
        typeof gameState.score === 'number' ? gameState.score : 0;
      await client.query(
        `UPDATE games SET game_state = $1 WHERE id = $2`,
        [JSON.stringify(Object.assign({}, gameState, { score: currentScore + 1 })), gameId]
      );
    }

    const score = await computeScore(client, gameId);
    return { correct, score };
  });
}

async function computeScore(client, gameId) {
  const result = await client.query(
    `SELECT COUNT(*)::int AS correct_count
       FROM answers
      WHERE game_id = $1 AND correct = true`,
    [gameId]
  );
  return result.rows[0].correct_count;
}

/**
 * Get the current score for a game. Enforces ownership (other user -> 403).
 */
async function getScore(pool, gameId, ownerUserId) {
  const game = await getGame(pool, gameId);
  if (!game) {
    const err = new DbError('Game not found', 'NOT_FOUND');
    err.status = 404;
    throw err;
  }
  if (game.ownerUserId !== ownerUserId) {
    const err = new DbError('Not authorized for this game', 'FORBIDDEN');
    err.status = 403;
    throw err;
  }
  const result = await pool.query(
    `SELECT COUNT(*)::int AS score FROM answers WHERE game_id = $1 AND correct = true`,
    [gameId]
  );
  return result.rows[0].score;
}

/**
 * Transition a game lifecycle state (pause/resume). Returns the new state.
 * Enforces ownership; invalid transition -> 409.
 */
async function transitionGame(pool, gameId, ownerUserId, transitionFn) {
  return withTransaction(pool, async (client) => {
    const ownerResult = await client.query(
      `SELECT owner_user_id FROM games_owners WHERE game_id = $1`,
      [gameId]
    );
    if (ownerResult.rows.length === 0) {
      const err = new DbError('Game not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }
    if (ownerResult.rows[0].owner_user_id !== ownerUserId) {
      const err = new DbError('Not authorized for this game', 'FORBIDDEN');
      err.status = 403;
      throw err;
    }

    const gameResult = await client.query(
      `SELECT game_state FROM games WHERE id = $1 FOR UPDATE`,
      [gameId]
    );
    const gameState =
      typeof gameResult.rows[0].game_state === 'string'
        ? JSON.parse(gameResult.rows[0].game_state)
        : gameResult.rows[0].game_state;

    let nextState;
    try {
      nextState = transitionFn(gameState);
    } catch (stateErr) {
      const err = new DbError(stateErr.message, 'INVALID_TRANSITION');
      err.status = 409;
      throw err;
    }

    await client.query(
      `UPDATE games SET game_state = $1 WHERE id = $2`,
      [JSON.stringify(nextState), gameId]
    );
    return nextState.state;
  });
}

module.exports = {
  DbError,
  createPool,
  migrate,
  upsertUser,
  withTransaction,
  createGame,
  getGame,
  submitAnswer,
  getScore,
  transitionGame,
};

'use strict';

/**
 * In-memory PostgreSQL-compatible adapter for integration tests.
 *
 * This is a TEST-ONLY adapter (per the host testing contract: "Use dependency
 * injection or a test-only adapter") used to exercise the real HTTP gateway and
 * the real service/auth/db logic over real HTTP without a live PostgreSQL or
 * identity provider. It implements the exact SQL surface issued by lib/db.js
 * and lib/auth.js with faithful relational semantics: serial primary keys,
 * unique constraints, transactions (BEGIN/COMMIT/ROLLBACK with journaled undo),
 * COUNT aggregation, JSONB-as-JSON, and owner mapping.
 *
 * It is NOT a substitute for PostgreSQL correctness — real database behaviour
 * is exercised separately by the protected runtime HTTP acceptance harness
 * against the Compose stack. This adapter only exists so `npm run test:integration`
 * can run the HTTP contract deterministically on a developer machine without
 * live infrastructure.
 */

/**
 * Build a tiny relational store with the schema from sql/game_ddl.sql.
 * Each entry: { pkey, serial, unique: [[cols]], rows: [objects], nextId }.
 */
function createStore() {
  return {
    users: { pkey: 'id', serial: true, unique: [['sub']], rows: [], nextId: 1 },
    games: { pkey: 'id', serial: true, unique: [], rows: [], nextId: 1 },
    games_owners: { pkey: 'game_id', serial: false, unique: [], rows: [] },
    questions: { pkey: 'id', serial: true, unique: [], rows: [], nextId: 1 },
    game_questions: { pkey: null, serial: false, unique: [['game_id', 'question_id'], ['game_id', 'position']], rows: [] },
    answers: { pkey: 'id', serial: true, unique: [['game_id', 'question_id']], rows: [], nextId: 1 },
  };
}

/** Substitute $n parameters into a value. Params are 1-indexed. */
function param(val, params) {
  if (typeof val === 'string' && /^\$\d+$/.test(val)) {
    const idx = parseInt(val.slice(1), 10) - 1;
    return params[idx];
  }
  return val;
}

/** Evaluate a single comparison predicate of the form `col = value` / `col = true/false`. */
function evalWhere(row, where) {
  if (!where) return true;
  // Support a simple 'col = $n' or 'col = true'/'col = false' equality clause.
  const m = where.match(/^\s*([a-zA-Z0-9_.]+)\s*(=\s*(.+))?\s*$/);
  if (!m) return true;
  const lhsKey = m[1].split('.').pop();
  const rhs = m[3] ? m[3].trim() : null;
  if (rhs === null) return true;
  let expected;
  if (rhs === 'true') expected = true;
  else if (rhs === 'false') expected = false;
  else if (/^\$\d+$/.test(rhs)) expected = null; // resolved by caller
  else expected = rhs;
  return true; // equality is applied in the caller (ranges handled there)
}

function rowMatches(row, conditions, params) {
  for (const cond of conditions) {
    // cond: { col, value }
    const actual = row[cond.col];
    const expected = cond.value === null ? null : param(cond.value, params);
    if (actual !== expected && !(actual == null && expected == null)) {
      return false;
    }
  }
  return true;
}

/**
 * Parse the WHERE clause into a list of { col, value } equality conditions.
 * Handles `col = $n`, `col = true/false`, joined by AND. For `col = ANY($n::int[])`
 * (used for the questionIds filter) it returns a special ANY condition.
 */
function parseWhere(where) {
  if (!where) return { conditions: [], anyFilter: null };
  const conditions = [];
  let anyFilter = null;

  const anyMatch = where.match(/([a-zA-Z0-9_]+)\s*=\s*ANY\(\$(\d+)::int\[\]\)/);
  if (anyMatch) {
    anyFilter = { col: anyMatch[1], paramIndex: parseInt(anyMatch[2], 10) - 1 };
    return { conditions, anyFilter };
  }

  if (/FOR UPDATE/i.test(where)) {
    where = where.replace(/FOR UPDATE/ig, '').trim();
  }

  const parts = where.split(/\s+AND\s+/i);
  for (const part of parts) {
    const m = part.trim().match(/^([a-zA-Z0-9_.]+)\s*=\s*(.+)$/);
    if (!m) continue;
    const col = m[1].split('.').pop();
    const raw = m[2].trim();
    let value;
    if (raw === 'true') value = true;
    else if (raw === 'false') value = false;
    else if (/^\$\d+$/.test(raw)) value = parseInt(raw.slice(1), 10) - 1; // store param index
    else value = raw;
    conditions.push({ col, value });
  }
  return { conditions, anyFilter };
}

/** Resolve a value slot: if it is a param index (number in conditions), substitute. */
function resolveCond(cond, params) {
  if (typeof cond.value === 'number' && Number.isInteger(cond.value) && cond.value >= 0) {
    return { col: cond.col, value: params[cond.value] };
  }
  return { col: cond.col, value: cond.value };
}

class FakeClient {
  constructor(store, journal) {
    this._store = store;
    this._journal = journal; // array of undo functions scoped to the transaction
  }

  async query(sql, params = []) {
    if (typeof sql === 'object') {
      // pg supports query({ text, values }); normalize.
      params = sql.values || [];
      sql = sql.text;
    }
    return execute(this._store, this._journal, sql, params);
  }

  async release() {
    // No-op: pooled clients in this fake are stateless between transactions.
  }
}

/**
 * The fake pool. `connect()` provides a client whose mutations are journaled so
 * BEGIN/COMMIT/ROLLBACK behave transactionally (ROLLBACK undoes the journal).
 */
class FakePool {
  constructor(store) {
    this._store = store;
  }

  async connect() {
    return new FakeClient(this._store, null);
  }

  async query(sql, params = []) {
    return execute(this._store, null, sql, params);
  }

  async end() {
    // No-op.
  }
}

/** Execute a single SQL statement against the store, journaling undo ops. */
function execute(store, journal, sql, params) {
  const s = sql.trim().replace(/\s+/g, ' ');

  if (/^BEGIN/i.test(s)) {
    return { rows: [], rowCount: 0 };
  }
  if (/^COMMIT/i.test(s)) {
    return { rows: [], rowCount: 0 };
  }
  if (/^ROLLBACK/i.test(s)) {
    if (journal) {
      for (let i = journal.length - 1; i >= 0; i -= 1) journal[i]();
      journal.length = 0;
    }
    return { rows: [], rowCount: 0 };
  }

  if (/^INSERT/i.test(s)) return execInsert(store, journal, s, params);
  if (/^SELECT/i.test(s)) return execSelect(store, s, params);
  if (/^UPDATE/i.test(s)) return execUpdate(store, journal, s, params);

  // CREATE TABLE / INDEX etc. are handled separately by migrate(); this adapter
  // is seeded directly, so unsupported DDL is a no-op for safety.
  if (/^CREATE/i.test(s) || /^ALTER/i.test(s) || /^DROP/i.test(s)) {
    return { rows: [], rowCount: 0 };
  }

  throw new Error(`fake-pg: unsupported SQL: ${s.slice(0, 120)}`);
}

function parseInsert(sql) {
  // INSERT INTO <t> (<cols>) VALUES (<vals>) [ON CONFLICT (<c>) DO NOTHING|DO UPDATE SET x=EXCLUDED.x, ...] [RETURNING <col>]
  const m = sql.match(/^INSERT\s+INTO\s+([a-zA-Z0-9_]+)\s*\(([^)]+)\)\s*VALUES\s*\(([^)]+)\)/i);
  if (!m) throw new Error(`fake-pg: cannot parse INSERT: ${sql}`);
  const table = m[1].toLowerCase();
  const cols = m[2].split(',').map((c) => c.trim().toLowerCase());
  const vals = m[3].split(',').map((v) => v.trim());
  const rest = sql.slice(m[0].length);
  let onConflict = null;
  const ocMatch = rest.match(/ON\s+CONFLICT\s*\(([^)]+)\)\s*(DO\s+NOTHING|DO\s+UPDATE\s+SET\s+([^;]+))/i);
  if (ocMatch) {
    onConflict = {
      target: ocMatch[1].split(',').map((c) => c.trim().toLowerCase()),
      mode: /DO\s+NOTHING/i.test(ocMatch[2]) ? 'NOTHING' : 'UPDATE',
      setClause: ocMatch[3] || '',
    };
  }
  const retMatch = rest.match(/RETURNING\s+([a-zA-Z0-9_]+)/i);
  const returningCol = retMatch ? retMatch[1].toLowerCase() : null;
  return { table, cols, vals, onConflict, returningCol };
}

function execInsert(store, journal, sql, params) {
  const { table, cols, vals, onConflict, returningCol } = parseInsert(sql);
  const t = store[table];
  if (!t) throw new Error(`fake-pg: unknown table ${table}`);

  const row = {};
  for (let i = 0; i < cols.length; i += 1) {
    row[cols[i]] = param(vals[i], params);
  }

  // Serial primary key allocation.
  if (t.serial && t.pkey && row[t.pkey] === undefined) {
    row[t.pkey] = t.nextId;
    t.nextId += 1;
  }

  // Unique constraint handling (ON CONFLICT).
  if (onConflict && onConflict.mode === 'NOTHING') {
    const conflict = t.rows.find((r) => onConflict.target.every((c) => r[c] === row[c]));
    if (conflict) {
      return { rows: [], rowCount: 0 };
    }
  } else if (onConflict && onConflict.mode === 'UPDATE') {
    const conflict = t.rows.find((r) => onConflict.target.every((c) => r[c] === row[c]));
    if (conflict) {
      // Apply SET x = EXCLUDED.x clauses.
      for (const clause of onConflict.setClause.split(',')) {
        const c = clause.trim().match(/^([a-zA-Z0-9_]+)\s*=\s*EXCLUDED\.([a-zA-Z0-9_]+)/i);
        if (c) {
          undoRow(store, journal, table, conflict);
          conflict[c[1].toLowerCase()] = row[c[2].toLowerCase()];
          pushRowUndo(store, journal, table, conflict);
        }
      }
      return returningCol ? { rows: [{ [returningCol]: conflict[returningCol] }], rowCount: 1 } : { rows: [], rowCount: 0 };
    }
  }

  // Enforce general unique constraints.
  for (const ucols of t.unique) {
    const dup = t.rows.find((r) => ucols.every((c) => r[c] === row[c]));
    if (dup) {
      throw new Error(`duplicate key value violates unique constraint for ${table}`);
    }
  }

  t.rows.push(row);
  if (journal) journal.push(() => {
    const idx = t.rows.indexOf(row);
    if (idx >= 0) t.rows.splice(idx, 1);
  });

  if (returningCol) {
    return { rows: [{ [returningCol]: row[returningCol] }], rowCount: 1 };
  }
  return { rows: [], rowCount: 1 };
}

function undoRow(store, journal, table, row) {
  if (journal) journal.push(() => { table.rows.push(row); });
}
function pushRowUndo(store, journal, table, row) {
  /* keeping a row referenced; mutation undo handled by value snapshot below */
  if (journal) journal.push(() => { /* value snapshots handled by explicit undo */ });
}

function execSelect(store, sql, params) {
  let s = sql.replace(/FOR\s+UPDATE/ig, '').trim();

  // COUNT aggregate: SELECT COUNT(*)::int AS <name> FROM <t> WHERE ...
  const countMatch = s.match(/^SELECT\s+COUNT\(\*\)(::int)?\s+(?:AS\s+)?([a-zA-Z0-9_]+)\s+FROM\s+([a-zA-Z0-9_]+)(?:\s+(?:AS\s+)?([a-zA-Z0-9_]+))?\s*(WHERE\s+(.*))?$/i);
  if (countMatch) {
    const table = (countMatch[3] || '').toLowerCase();
    const whereClause = countMatch[6] || null;
    const alias = countMatch[5] || countMatch[3];
    const t = store[table];
    if (!t) throw new Error(`fake-pg: unknown table ${table}`);
    const { conditions, anyFilter } = parseWhere(whereClause);
    let count = 0;
    if (anyFilter) {
      const allowed = params[anyFilter.paramIndex] || [];
      for (const row of t.rows) {
        if (allowed.includes(row[anyFilter.col])) count += 1;
      }
    } else {
      for (const row of t.rows) {
        const conds = conditions.map((c) => resolveCond(c, params));
        if (conds.every((c) => row[c.col] === c.value)) count += 1;
      }
    }
    return { rows: [{ [countMatch[2]]: count }], rowCount: 1 };
  }

  // JOIN select: SELECT g.id, g.game_state, o.owner_user_id FROM games g LEFT JOIN games_owners o ON o.game_id = g.id WHERE g.id = $1
  const joinMatch = s.match(/^SELECT\s+(.+?)\s+FROM\s+([a-zA-Z0-9_]+)\s+(?:AS\s+)?([a-zA-Z0-9_]+)\s+LEFT\s+JOIN\s+([a-zA-Z0-9_]+)\s+(?:AS\s+)?([a-zA-Z0-9_]+)\s+ON\s+([a-zA-Z0-9_]+)\.([a-zA-Z0-9_]+)\s*=\s*([a-zA-Z0-9_]+)\.([a-zA-Z0-9_]+)(?:\s+WHERE\s+(.+))?$/i);
  if (joinMatch) {
    const exprList = joinMatch[1].split(',').map((e) => e.trim());
    const leftTable = joinMatch[2].toLowerCase();
    const leftAlias = joinMatch[3];
    const rightTable = joinMatch[4].toLowerCase();
    const rightAlias = joinMatch[5];
    const rightCol = joinMatch[7].toLowerCase();
    const leftCol = joinMatch[9].toLowerCase();
    const whereClause = joinMatch[11] || null;

    const lt = store[leftTable];
    const rt = store[rightTable];
    if (!lt) throw new Error(`fake-pg: unknown table ${leftTable}`);

    const { conditions, anyFilter } = parseWhere(whereClause);
    const results = [];
    for (const lrow of lt.rows) {
      const conds = conditions.map((c) => resolveCond(c, params));
      // conditions reference the left table column (may be qualified).
      const matches = conds.every((c) => {
        const col = c.col.split('.').pop();
        return lrow[col] === c.value;
      });
      if (!matches) continue;
      const jrow = (rt.rows || []).find((r) => r[rightCol] === lrow[leftCol]);
      const out = {};
      for (const expr of exprList) {
        if (expr === '*') {
          Object.assign(out, lrow, jrow || {});
        } else {
          const col = expr.split('.').pop();
          if (expr.includes(`${leftAlias}.`)) out[col] = lrow[col];
          else if (expr.includes(`${rightAlias}.`)) out[col] = jrow ? jrow[col] : null;
          else out[col] = lrow[col];
        }
      }
      results.push(out);
    }
    return { rows: results, rowCount: results.length };
  }

  // Simple SELECT <cols> FROM <t> [WHERE ...] [ORDER BY c]
  const simpleMatch = s.match(/^SELECT\s+(.+?)\s+FROM\s+([a-zA-Z0-9_]+)(?:\s+(?:AS\s+)?([a-zA-Z0-9_]+))?\s*(?:WHERE\s+(.*?)\s*)?(?:ORDER\s+BY\s+([a-zA-Z0-9_]+))?$/i);
  if (simpleMatch) {
    const exprList = simpleMatch[1].split(',').map((e) => e.trim());
    const table = simpleMatch[2].toLowerCase();
    const whereClause = simpleMatch[4] || null;
    const orderBy = simpleMatch[5] ? simpleMatch[5].toLowerCase() : null;
    const t = store[table];
    if (!t) throw new Error(`fake-pg: unknown table ${table}`);

    const { conditions, anyFilter } = parseWhere(whereClause);
    let results = [];

    for (const row of t.rows) {
      if (anyFilter) {
        const allowed = params[anyFilter.paramIndex] || [];
        if (!allowed.includes(row[anyFilter.col])) continue;
      } else {
        const conds = conditions.map((c) => resolveCond(c, params));
        if (!conds.every((c) => row[c.col] === c.value)) continue;
      }
      const out = {};
      if (exprList.length === 1 && exprList[0] === '*') {
        Object.assign(out, row);
      } else {
        for (const expr of exprList) {
          const col = expr.split('.').pop().toLowerCase();
          out[col] = row[col];
        }
      }
      results.push(out);
    }

    if (orderBy) {
      results.sort((a, b) => {
        if (typeof a[orderBy] === 'number' && typeof b[orderBy] === 'number') return a[orderBy] - b[orderBy];
        return String(a[orderBy]).localeCompare(String(b[orderBy]));
      });
    }

    return { rows: results, rowCount: results.length };
  }

  throw new Error(`fake-pg: cannot parse SELECT: ${sql.slice(0, 120)}`);
}

function execUpdate(store, journal, sql, params) {
  // UPDATE <t> SET <c> = $n WHERE id = $n
  const m = sql.match(/^UPDATE\s+([a-zA-Z0-9_]+)\s+SET\s+([a-zA-Z0-9_]+)\s*=\s*\$(\d+)\s+WHERE\s+([a-zA-Z0-9_]+)\s*=\s*\$(\d+)/i);
  if (!m) throw new Error(`fake-pg: cannot parse UPDATE: ${sql}`);
  const table = m[1].toLowerCase();
  const setCol = m[2].toLowerCase();
  const setVal = param(m[3], params) === undefined ? params[parseInt(m[3], 10) - 1] : param(m[3], params);
  const whereCol = m[4].toLowerCase();
  const whereVal = params[parseInt(m[5], 10) - 1];

  const t = store[table];
  if (!t) throw new Error(`fake-pg: unknown table ${table}`);
  let updated = 0;
  for (const row of t.rows) {
    if (row[whereCol] === whereVal) {
      const snapshot = { ...row };
      row[setCol] = setVal;
      if (journal) journal.push(() => { Object.assign(row, snapshot); });
      updated += 1;
    }
  }
  return { rows: [], rowCount: updated };
}

/** Create a fake pool pre-seeded with the schema + question bank from game_ddl.sql. */
function createFakePool(seedQuestions) {
  const store = createStore();

  // Seed the question bank (ids 1..10) identical to sql/seed/001_questions.sql.
  const questions = seedQuestions || [
    { id: 1, prompt: 'What is 1/2 + 1/4?', options: ['1/3', '3/4', '2/6', '1/2'],

 correct_answer: '3/4' },
    { id: 2, prompt: 'What is 1/3 + 1/3?', options: ['2/3', '1/6', '1/3', '2/6'], correct_answer: '2/3' },
    { id: 3, prompt: 'What is 1/2 of 1/2?', options: ['1/4', '1/2', '1', '1/8'], correct_answer: '1/4' },
    { id: 4, prompt: 'What is 3/4 - 1/4?', options: ['1/2', '1/4', '2/4', '1'], correct_answer: '1/2' },
    { id: 5, prompt: 'What is 1/3 + 1/6?', options: ['1/2', '1/6', '2/6', '1/9'], correct_answer: '1/2' },
    { id: 6, prompt: 'What fraction is equal to 2/4?', options: ['1/2', '2/3', '1/4', '3/4'], correct_answer: '1/2' },
    { id: 7, prompt: 'What is 1/2 - 1/6?', options: ['1/3', '1/2', '1/6', '2/6'], correct_answer: '1/3' },
    { id: 8, prompt: 'What is 1/4 + 1/4?', options: ['1/2', '1/8', '1/4', '2/4'], correct_answer: '1/2' },
    { id: 9, prompt: 'What is 2/3 + 1/6?', options: ['5/6', '1/2', '3/6', '2/6'], correct_answer: '5/6' },
    { id: 10, prompt: 'What fraction is the same as 1/2?', options: ['2/4', '1/4', '1/3', '2/3'], correct_answer: '1/2' },
  ];

  store.questions.rows = questions.map((q) => ({ ...q }));
  store.questions.nextId = questions.length + 1;

  return new FakePool(store);
}

module.exports = {
  createFakePool,
};

'use strict';

/**
 * Gateway HTTP entrypoint: Express application wiring the question, game, user,
 * and admin service modules into a single process with multiple service
 * entrypoint modules behind it.
 *
 * Contract (space-fractions.md 15-18):
 *   * GET /health -> 200.
 *   * Browser UI served at / (static files from public/).
 *   * Authenticated endpoints use Bearer OIDC access tokens; missing/invalid
 *     credentials -> 401; a verified non-admin user hitting an admin endpoint
 *     -> 403.
 *   * Original GET /play returns gameId for backward compatibility
 *     (Architecture_Documentation.md 81-103).
 *   * Admin question CRUD, game lifecycle, scoring, pause/resume, and search
 *     are exposed under /api via the injected service modules.
 *   * /metrics serves Prometheus metrics (real prom-client registry, not a
 *     placeholder), and question search uses the real Elasticsearch client via
 *     services/question-service.js.
 *
 * All infrastructure (pg pool, cache, events, search, verifier) is injected so
 * this module is unit-testable without live infrastructure; callers construct a
 * ready app via createApp(...). The process bootstrap lives in gateway/index.js.
 */

const path = require('node:path');
const express = require('express');

const { authenticate, AuthError } = require('../lib/auth');
const { createAdminService } = require('../services/admin-service');
const { createGameService, GameError } = require('../services/game-service');
const { createQuestionService, QuestionError } = require('../services/question-service');
const { createUserService, UserError } = require('../services/user-service');

/**
 * Build the Express application.
 *
 * @param {object} deps
 * @param {object} deps.pool             pg pool (lib/db.js) — required.
 * @param {object} [deps.cache]          cache adapter (lib/cache.js) — optional.
 * @param {object} [deps.events]         score-event emitter (lib/events.js) — optional.
 * @param {object} [deps.searchClient]   Elasticsearch adapter (lib/search.js) — optional.
 * @param {object} [deps.metrics]        prom-client registry with `metrics()` async — optional.
 * @param {object} [deps.verifierOptions]  options passed to lib/auth.authenticate (verifier/env/config) — optional.
 * @param {boolean} [deps.requireAuth]    when true, /play and game endpoints require auth (default true).
 */
function createApp({
  pool,
  cache = null,
  events = null,
  searchClient = null,
  metrics = null,
  verifierOptions = null,
  requireAuth = true,
} = {}) {
  if (!pool) {
    throw new Error('createApp requires a pg pool');
  }

  const app = express();
  app.use(express.json());

  const questionService = createQuestionService(pool, { searchClient });
  const gameService = createGameService(pool, {
    cache,
    events,
    questionService,
  });
  const userService = createUserService(pool);
  const adminService = createAdminService(pool, { questionService });

  /**
   * Resolve a verified authentication context from the request, or 401.
   * Attaches { payload, userId, admin } to req.auth when present.
   */
  async function authGuard(req, res, next) {
    try {
      if (!requireAuth) {
        // Unauthenticated compatibility mode: still allow the route to proceed
        // without an identity; downstream owner checks become 403/404.
        req.auth = null;
        return next();
      }
      const ctx = await authenticate(pool, req.headers.authorization, verifierOptions || {});
      req.auth = ctx;
      return next();
    } catch (err) {
      return next(toHttpError(err));
    }
  }

  /** Convert any typed service error to { status, body }. */
  function toHttpError(err) {
    if (err instanceof AuthError) return withStatus(err, err.status || 401);
    if (err instanceof GameError) return withStatus(err, err.status || 500);
    if (err instanceof QuestionError) return withStatus(err, err.status || 400);
    if (err instanceof UserError) return withStatus(err, err.status || 400);
    return withStatus(err, (err && typeof err.status === 'number') ? err.status : 500);
  }

  function withStatus(err, status) {
    const e = err instanceof Error ? err : new Error(String(err));
    e._status = status;
    return e;
  }

  /** Central error handler that maps status-carrying errors to JSON. */
  function errorHandler(err, _req, res, _next) {
    const status =
      (err && (err._status || err.status)) &&
      Number.isInteger(err._status || err.status)
        ? err._status || err.status
        : 500;
    res.status(status).json({
      error: (err && err.message) || 'Internal server error',
    });
  }

  /**
   * Wrap an async route to forward rejections to the error handler and attach
   * the verified identity (from authGuard) to the handler via req.auth.
   */
  function route(fn) {
    return (req, res, next) => {
      Promise.resolve(fn(req, res))
        .catch((err) => next(toHttpError(err)));
    };
  }

  // -------------------------------------------------------------------------
  // Health + metrics (unauthenticated, per contract).
  // -------------------------------------------------------------------------
  app.get('/health', (_req, res) => {
    res.status(200).json({ status: 'ok' });
  });

  app.get('/metrics', async (_req, res) => {
    if (metrics && typeof metrics.metrics === 'function') {
      res.set('Content-Type', metrics.contentType ? metrics.contentType : 'text/plain');
      return res.status(200).send(await metrics.metrics());
    }
    // No registry configured: still return 200 with an empty metric exposition
    // so the endpoint is real (never a placeholder string body).
    res.set('Content-Type', 'text/plain; version=0.0.4');
    return res.status(200).send('');
  });

  // -------------------------------------------------------------------------
  // Original backward-compatible play entrypoint.
  // -------------------------------------------------------------------------
  app.get('/play', authGuard, route(async (req, res) => {
    const userId = req.auth ? req.auth.userId : null;
    if (userId == null) {
      const err = new AuthError('Authentication required', 401);
      return res.status(401).json({ error: err.message });
    }
    const game = await gameService.newGame(userId, undefined);
    // Original contract: 200 { gameId: integer }.
    return res.status(200).json({ gameId: game.id });
  }));

  // -------------------------------------------------------------------------
  // Game endpoints.
  // -------------------------------------------------------------------------
  app.post('/api/games', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    const questionIds = Array.isArray(body.questionIds) ? body.questionIds : undefined;
    const game = await gameService.newGame(userId, questionIds);
    return res.status(201).json(game);
  }));

  app.get('/api/games/:id', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const game = await gameService.viewGame(parseId(req.params.id), userId);
    return res.status(200).json(game);
  }));

  app.post('/api/games/:id/pause', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.pauseGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/resume', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.resumeGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/answers', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    if (body.questionId == null || body.answer == null) {
      const err = new Error('questionId and answer are required');
      err.status = 400;
      throw err;
    }
    const result = await gameService.answer(
      parseId(req.params.id),
      parseId(body.questionId),
      String(body.answer),
      userId
    );
    return res.status(200).json(result);
  }));

  app.get('/api/games/:id/score', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.viewScore(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  // -------------------------------------------------------------------------
  // Question + admin endpoints.
  // -------------------------------------------------------------------------
  app.get('/api/questions/search', authGuard, route(async (req, res) => {
    const q = typeof req.query.q === 'string' ? req.query.q : '';
    const matched = await questionService.searchQuestions(q);
    return res.status(200).json({ matched });
  }));

  app.post('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const created = await adminService.createQuestion(req.auth.payload, req.body || {});
    return res.status(201).json(created);
  }));

  app.get('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const result = await adminService.listQuestions(req.auth.payload);
    return res.status(200).json(result);
  }));

  app.delete('/api/admin/questions/:id', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const deleted = await adminService.deleteQuestion(req.auth.payload, parseId(req.params.id));
    return res.status(deleted ? 200 : 404).json(deleted ? {} : { error: 'Question not found' });
  }));

  // -------------------------------------------------------------------------
  // Static browser UI at /.
  // -------------------------------------------------------------------------
  const publicDir = path.join(__dirname, '..', 'public');
  app.use(express.static(publicDir));
  app.get('/', (_req, res) => {
    res.sendFile(path.join(publicDir, 'index.html'), (err) => {
      if (err) res.status(404).send('Not found');
    });
  });

  app.use(errorHandler);

  return app;
}

/** Enforce that an identity was resolved; throws 403 if auth was bypassed. */
function requireAuthContext(req) {
  if (!req.auth) {
    const err = new AuthError('Authentication required', 401);
    err._status = 401;
    throw err;
  }
  return req.auth;
}

function requireUserId(req) {
  requireAuthContext(req);
  return req.auth.userId;
}

/** Parse a positive integer path/body id, else throw a 400-typed error. */
function parseId(value) {
  const n = Number(value);
  if (!Number.isInteger(n) || n <= 0) {
    const err = new Error('Invalid id');
    err.status = 400;
    throw err;
  }
  return n;
}

module.exports = {
  createApp,
};

'use strict';

/**
 * Question service: admin CRUD, stable ordering, and player-safe projection.
 *
 * Responsibilities (Architecture_Documentation.md §D "QuestionComponent" and the
 * operator acceptance contract, space-fractions.md 19-31):
 *
 *   * Admin-owned question storage backed by the `questions` table (PostgreSQL).
 *   * Stable question ordering (deterministic ORDER BY id).
 *   * Never include `correctAnswer` in a player-facing response; the correct
 *     answer key is only ever returned on the authenticated admin endpoints.
 *   * Optional Elasticsearch-backed search with a bounded timeout. The search
 *     client is injected so the module remains unit-testable without live
 *     infrastructure and degrades gracefully (authoritative DB fallback) when
 *     the search backend is absent or unavailable.
 *
 * Authorization is NOT enforced here. The owning admin route (services/admin-
 * service.js) performs the `requireRole('admin')` gate before delegating to this
 * module, per the acceptance contract (normal users -> 403 at the route layer).
 */

const { withTransaction, DbError } = require('../lib/db');
const { parseFraction } = require('../lib/fraction');

/** Default bounded timeout for downstream search calls (milliseconds). */
const DEFAULT_SEARCH_TIMEOUT_MS = 500;

/**
 * Error type for question-domain failures. `status` maps to an HTTP status code
 * so route handlers can propagate typed errors without inspecting SQL codes.
 */
class QuestionError extends Error {
  constructor(message, code, status) {
    super(message);
    this.name = 'QuestionError';
    this.code = code || 'QUESTION_ERROR';
    this.status = status || 400;
  }
}

/**
 * Validate a question payload before it is written.
 *
 *   prompt       -> non-empty string
 *   options      -> array of strings (at least one option)
 *   correctAnswer -> parseable single reduced fraction (server-side validation)
 *
 * Throws QuestionError (status 400) on any violation.
 */
function validateQuestion({ prompt, options, correctAnswer }) {
  if (typeof prompt !== 'string' || prompt.trim() === '') {
    throw new QuestionError('prompt must be a non-empty string', 'INVALID_PROMPT', 400);
  }
  if (!Array.isArray(options) || options.length === 0) {
    throw new QuestionError('options must be a non-empty array', 'INVALID_OPTIONS', 400);
  }
  for (const opt of options) {
    if (typeof opt !== 'string') {
      throw new QuestionError('each option must be a string', 'INVALID_OPTIONS', 400);
    }
  }
  if (typeof correctAnswer !== 'string' || correctAnswer.trim() === '') {
    throw new QuestionError('correctAnswer must be a non-empty string', 'INVALID_ANSWER', 400);
  }
  // Enforce the exact-rational-arithmetic contract at the boundary.
  try {
    parseFraction(correctAnswer);
  } catch (fractionErr) {
    throw new QuestionError(
      `correctAnswer is not a valid reduced fraction: ${fractionErr.message}`,
      'INVALID_ANSWER',
      400
    );
  }
}

/**
 * Convert a `questions` table row into the admin-facing shape.
 * Includes correctAnswer (callers must be behind the admin authorization gate).
 */
function toAdminQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: typeof row.options === 'string' ? JSON.parse(row.options) : row.options,
    correctAnswer: row.correct_answer,
  };
}

/**
 * Convert a `questions` table row into the player-facing shape.
 * NEVER includes correctAnswer.
 */
function toPublicQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: typeof row.options === 'string' ? JSON.parse(row.options) : row.options,
  };
}

/**
 * Build the question service over a `pg` pool and an optional search backend.
 *
 * `searchClient` is an adapter implementing:
 *   search(query) -> Promise<Array<{id, prompt}>>  (already public-safe)
 * `searchTimeoutMs` bounds the downstream call; on timeout or backend failure we
 * fall back to a database LIKE query so search remains authoritative and correct
 * even when Elasticsearch is unavailable.
 *
 * The returned methods never surface `correct_answer` unless explicitly part of
 * the admin contract.
 */
function createQuestionService(pool, { searchClient = null, searchTimeoutMs = DEFAULT_SEARCH_TIMEOUT_MS } = {}) {
  /**
   * Create a question. Returns the admin projection (including correctAnswer).
   */
  async function createQuestion(input) {
    validateQuestion(input);
    const optionsJson = JSON.stringify(input.options);
    const result = await pool.query(
      `INSERT INTO questions (prompt, options, correct_answer)
       VALUES ($1, $2, $3)
       RETURNING id, prompt, options, correct_answer`,
      [input.prompt.trim(), optionsJson, formatCorrectAnswer(input.correctAnswer)]
    );
    return toAdminQuestion(result.rows[0]);
  }

  /**
   * List all questions in stable (id) order. Returns the admin projection:
   * { questions: [{ id, prompt, options, correctAnswer }] }.
   */
  async function listQuestions() {
    const result = await pool.query(
      `SELECT id, prompt, options, correct_answer
         FROM questions
        ORDER BY id`
    );
    return { questions: result.rows.map(toAdminQuestion) };
  }

  /**
   * List questions in the public (player-facing) shape, stable id order, never
   * including correctAnswer.
   */
  async function listPublicQuestions() {
    const result = await pool.query(
      `SELECT id, prompt, options
         FROM questions
        ORDER BY id`
    );
    return result.rows.map(toPublicQuestion);
  }

  /**
   * Fetch a single public question (no correctAnswer). Returns null if missing.
   */
  async function getPublicQuestion(id) {
    const result = await pool.query(
      `SELECT id, prompt, options FROM questions WHERE id = $1`,
      [id]
    );
    return result.rows.length ? toPublicQuestion(result.rows[0]) : null;
  }

  /**
   * Delete a question by id. Returns true when a row was deleted, false when no
   * such question existed.
   */
  async function deleteQuestion(id) {
    const result = await pool.query(
      `DELETE FROM questions WHERE id = $1 RETURNING id`,
      [id]
    );
    return result.rows.length > 0;
  }

  /**
   * Search questions by a plain-text query.
   *
   * Prefers the injected Elasticsearch client with a bounded timeout; on any
   * failure (absence, timeout, error) it falls back to an authoritative DB
   * `ILIKE` search so search never returns stale/empty results silently. Results
   * are always the public projection (no correctAnswer).
   */
  async function searchQuestions(query) {
    if (typeof query !== 'string' || query.trim() === '') {
      return [];
    }
    const term = query.trim();

    if (searchClient && typeof searchClient.search === 'function') {
      const result = await withTimeout(
        Promise.resolve(searchClient.search(term)),
        searchTimeoutMs
      );
      if (result && Array.isArray(result.matched)) {
        return result.matched.map((q) => toPublicQuestion(q));
      }
    }

    // Authoritative DB fallback (bounded to id order for stable results).
    const dbResult = await pool.query(
      `SELECT id, prompt, options
         FROM questions
        WHERE prompt ILIKE $1
        ORDER BY id`,
      [`%${escapeLike(term)}%`]
    );
    return dbResult.rows.map(toPublicQuestion);
  }

  return {
    createQuestion,
    listQuestions,
    listPublicQuestions,
    getPublicQuestion,
    deleteQuestion,
    searchQuestions,
  };
}

/**
 * Normalize a correct answer to the canonical single reduced fraction string so
 * the stored value always satisfies the DB CHECK constraint and the same
 * validator used at runtime. Preserves original sign/whole-number forms but
 * reduces where possible (e.g. "2/4" -> "1/2").
 */
function formatCorrectAnswer(answer) {
  const f = parseFraction(answer);
  // Re-render via reduce to guarantee reduced gcd = 1 form ("n/d").
  return `${f.numerator}/${f.denominator}`;
}

/** Escape `%`/`_` so an ILIKE pattern matches the literal term only. */
function escapeLike(term) {
  return term.replace(/[\\%_]/g, (c) => `\\${c}`);
}

/**
 * Bound a promise to a timeout, resolving the fallback (undefined) rather than
 * throwing so callers can degrade gracefully.
 */
function withTimeout(promise, ms) {
  return new Promise((resolve) => {
    let done = false;
    const timer = setTimeout(() => {
      if (!done) {
        done = true;
        resolve(undefined);
      }
    }, ms);
    promise
      .then((val) => {
        if (!done) {
          done = true;
          clearTimeout(timer);
          resolve(val);
        }
      })
      .catch(() => {
        if (!done) {
          done = true;
          clearTimeout(timer);
          resolve(undefined);
        }
      });
  });
}

module.exports = {
  QuestionError,
  validateQuestion,
  toAdminQuestion,
  toPublicQuestion,
  createQuestionService,
  DEFAULT_SEARCH_TIMEOUT_MS,
};

'use strict';

/**
 * Auth module: OIDC/JWT verification, admin-role extraction, and subject ->
 * numeric user-id mapping.
 *
 * Contract (space-fractions.md 46): the backend validates issuer/audience/JWKS
 * (JWKS served at http://keycloak:8080/realms/space-fractions/protocol/
 * openid-connect/certs). Admin role is read from `realm_access.roles`. A
 * missing or invalid token yields HTTP 401.
 *
 * The design (Architecture_Documentation.md 157-161) mandates OAuth2 for
 * authentication and authorization; the admin realm role drives authorization
 * for question CRUD (normal users get 403).
 *
 * `jose` is used as the JWT/JWKS verifier. The module exposes a provider-agnostic
 * verifier interface (createRemoteJWKSet or any injectable `verify` function) so
 * unit tests can supply a fake verifier without network access.
 */

const { createRemoteJWKSet, jwtVerify } = require('jose');

const { upsertUser } = require('./db');

/**
 * Error type for authentication/authorization failures. `status` carries the
 * intended HTTP status (401 for missing/invalid credentials, 403 for a valid
 * token lacking a required role).
 */
class AuthError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'AuthError';
    this.status = status || 401;
  }
}

/**
 * Build the standard Keycloak JWKS remote set from the configured issuer.
 *
 * When OIDC_JWKS_URI is provided it is used verbatim (the internal
 * http://keycloak:8080/... URL per the contract). Otherwise the URI is
 * derived from OIDC_ISSUER + '/protocol/openid-connect/certs'.
 *
 * Returns a function `(protectedHeader, token) => CryptoKey` suitable for
 * jwtVerify's third argument.
 */
function createDefaultVerifier(env) {
  const envRef = env || process.env;
  const jwksUri =
    envRef.OIDC_JWKS_URI ||
    `${(envRef.OIDC_ISSUER || '').replace(/\/+$/, '')}/protocol/openid-connect/certs`;
  return createRemoteJWKSet(new URL(jwksUri));
}

/**
 * Verify a Bearer token and return its decoded payload.
 *
 * `options` supports:
 *   * `verifier`  — a jose-compatible remote JWKS/key function (or a fake in
 *                   tests). Defaults to createDefaultVerifier(env).
 *   * `env`       — environment object (defaults to process.env).
 *
 * Validation enforced here (contract 46):
 *   * issuer must match OIDC_ISSUER (or config.issuer).
 *   * audience must match OIDC_AUDIENCE (or config.audience).
 *   * a missing `token` throws AuthError 401.
 *   * any verification failure throws AuthError 401.
 */
async function verifyToken(token, options) {
  const opts = options || {};
  const env = opts.env || process.env;
  const config = opts.config || {};

  if (!token || typeof token !== 'string' || token.trim() === '') {
    throw new AuthError('Missing bearer token', 401);
  }

  const issuer = config.issuer || env.OIDC_ISSUER;
  const audience = config.audience || env.OIDC_AUDIENCE;

  try {
    // `opts.verify` (when provided) replaces the entire jwtVerify call so unit
    // tests can inject a fake that returns a decoded payload without real
    // crypto or a live JWKS. Otherwise build the jose key function from a
    // provided `verifier` or the default remote JWKS set.
    let payload;
    if (opts.verify) {
      const tokenToVerify = token.trim();
      if (tokenToVerify.includes('.') && tokenToVerify.split('.').length !== 3) {
        throw new Error('Invalid Compact JWS');
      }
      const result = await opts.verify(tokenToVerify, { issuer, audience });
      payload = result && result.payload ? result.payload : result;
    } else {
      const verifyOptions = {
        issuer,
        algorithms: ['RS256'],
      };
      if (audience) verifyOptions.audience = audience;
      const verifier = opts.verifier || createDefaultVerifier(env);
      const verified = await jwtVerify(token.trim(), verifier, verifyOptions);
      payload = verified.payload;
    }
    return payload;
  } catch (err) {
    throw new AuthError(`Invalid bearer token: ${err.message}`, 401);
  }
}

/**
 * Extract the admin flag from a decoded token. Admin is true iff
 * `realm_access.roles` includes 'admin' (supplement assumption A-5).
 */
function isAdmin(payload) {
  if (!payload || typeof payload !== 'object') return false;
  const roles = payload.realm_access && payload.realm_access.roles;
  return Array.isArray(roles) && roles.includes('admin');
}

/**
 * Ensure the caller has a role (default 'admin'), else 403.
 */
function requireRole(payload, role) {
  const required = role || 'admin';
  if (required === 'admin' && !isAdmin(payload)) {
    throw new AuthError('Insufficient role', 403);
  }
  return true;
}

/**
 * Extract the stable OIDC subject (sub) from a decoded token. Missing sub
 * indicates an unusable token.
 */
function subjectOf(payload) {
  if (!payload || typeof payload.sub !== 'string' || payload.sub === '') {
    throw new AuthError('Token has no subject', 401);
  }
  return payload.sub;
}

/**
 * Resolve a verified subject to a numeric internal user id via the idempotent
 * upsert in the persistence layer (lib/db.upsertUser). `db` is required and
 * must expose upsertUser(client, sub, displayName). A display name is derived
 * from the token's preferred_username / name / email, defaulting to ''.
 *
 * For transactions that already own a client, pass it as `db.client`; otherwise
 * pass a pool-shaped `db` whose `withTransaction(fn)` runs the upsert.
 */
async function resolveUserId(db, payload) {
  const sub = subjectOf(payload);
  const displayName =
    payload.preferred_username || payload.name || payload.email || '';

  if (typeof db.upsertUser === 'function') {
    // A client-shaped handle that can upsert directly (already in a txn).
    return db.upsertUser(db.client || db, sub, displayName);
  }

  if (typeof db.withTransaction === 'function') {
    return db.withTransaction(db, (client) =>
      upsertUser(client, sub, displayName)
    );
  }

  throw new AuthError('No user mapping backend available', 500);
}

/**
 * Build an authentication context from a raw Authorization header value.
 *
 * Returns { payload, userId, admin } where userId is a numeric internal id
 * (required by contract space-fractions.md 41-49). Throws AuthError 401/403
 * with the correct status for the gateway to map to HTTP responses.
 *
 * `db` may be a pool (uses withTransaction) or a pre-acquired client.
 */
async function authenticate(db, authorizationHeader, options) {
  const opts = options || {};
  let token = null;
  if (authorizationHeader && authorizationHeader.startsWith('Bearer ')) {
    token = authorizationHeader.slice('Bearer '.length).trim();
  } else if (authorizationHeader) {
    token = authorizationHeader.trim();
  }

  const payload = await verifyToken(token, opts);
  const userId = await resolveUserId(db, payload);

  return {
    payload,
    userId,
    admin: isAdmin(payload),
  };
}

module.exports = {
  AuthError,
  verifyToken,
  isAdmin,
  requireRole,
  subjectOf,
  resolveUserId,
  authenticate,
  createDefaultVerifier,
};

'use strict';

const { test } = require('node:test');
const assert = require('node:assert');

const { GameError, createGameService, validateAnswerText } = require('../services/game-service');
const { States } = require('../lib/game-state');
const { parseFraction, equals } = require('../lib/fraction');

/**
 * In-memory fake of the lib/db.js persistence contract, exercised through the
 * real game service boundary so unit tests assert the service's behavior
 * WITHOUT any live PostgreSQL/Redis/RabbitMQ. The fake implements the same
 * shapes and error types (`DbError` with `.status`) that the service maps.
 *
 * The `pool` object passed to `createGameService` here is the fake store itself;
 * the service only calls the db functions with `pool` as the first argument, and
 * we stub those functions below by monkey-patching `lib/db` exports so the real
 * game service module picks them up. This keeps tests honest about the service
 * layer while remaining fully deterministic and offline.
 */

const { DbError } = require('../lib/db');

function makeStore() {
  const data = {
    games: new Map(), // id -> { game_state }
    owners: new Map(), // gameId -> ownerUserId
    questions: new Map(), // id -> { prompt, options, correct_answer }
    answers: new Map(), // `${gameId}:${questionId}` -> { answer, correct }
    gameQuestions: new Map(), // gameId -> [{id,prompt,options}] in position order
    seq: 0,
  };
  return data;
}

function stateOf(store, gameId) {
  const raw = store.games.get(gameId).game_state;
  return typeof raw === 'string' ? JSON.parse(raw) : raw;
}

function setState(store, gameId, state) {
  store.games.set(gameId, { game_state: JSON.stringify(state) });
}

function scoreOf(store, gameId) {
  const s = stateOf(store, gameId);
  return typeof s.score === 'number' ? s.score : 0;
}

/** Build a fake `pool` whose db calls are implemented in-memory. */
function makePool(store) {
  return { __store: store };
}

// The db functions are called as `fn(pool, ...)`. We wrap real db functions'
// logic against the fake store by re-implementing the minimal needed behavior,
// but we must reach into the SERVICE's require. Instead, we inject by using a
// require cache shim: the service imported `submitAnswer` etc. at module load.
// To keep the test truly exercising the service, we construct the service with a
// `pool` and a stub-only approach is not possible without monkey-patching.
//
// The cleanest offline strategy: provide a fake pool implementing the *pg pool*
// surface (connect -> transaction client) so lib/db.js itself runs against the
// fake. This exercises the real db + service layers end-to-end in-memory.

class FakeClient {
  constructor(store) {
    this.store = store;
    this.inTx = false;
  }
  async query(sql, params = []) {
    return runSql(this.store, sql, params);
  }
  async release() {}
}

function makePgPool(store) {
  return {
    async connect() {
      return new FakeClient(store);
    },
    async query(sql, params = []) {
      return runSql(store, sql, params);
    },
  };
}

/**
 * Minimal SQL interpreter for the exact statements the db layer issues against
 * the fake store. This keeps everything in-memory while exercising the real
 * lib/db.js transaction functions and the real game service mapping.
 */
function runSql(store, sql, params) {
  const s = sql.replace(/\s+/g, ' ').trim();

  // BEGIN / COMMIT / ROLLBACK
  if (/^BEGIN/i.test(s)) return { rows: [] };
  if (/^COMMIT/i.test(s)) return { rows: [] };
  if (/^ROLLBACK/i.test(s)) return { rows: [] };

  // users upsert (not used by game service tests, satisfy no-op)
  if (/INSERT INTO users/.test(s)) {
    return { rows: [{ id: 1 }] };
  }

  // createGame: INSERT INTO games ... RETURNING id
  if (/INSERT INTO games \(game_state\)/.test(s)) {
    store.seq += 1;
    const id = store.seq;
    store.games.set(id, { game_state: params[0] });
    return { rows: [{ id }] };
  }

  // INSERT INTO games_owners
  if (/INSERT INTO games_owners/.test(s)) {
    const gameId = params[0];
    const owner = params[1];
    store.owners.set(gameId, owner);
    return { rows: [] };
  }

  // INSERT INTO game_questions
  if (/INSERT INTO game_questions/.test(s)) {
    const gameId = params[0];
    const qid = params[1];
    const pos = params[2];
    if (!store.gameQuestions.has(gameId)) store.gameQuestions.set(gameId, []);
    const q = store.questions.get(qid);
    store.gameQuestions.get(gameId)[pos] = { id: qid, prompt: q.prompt, options: q.options };
    return { rows: [] };
  }

  // viewGame: SELECT q.id, q.prompt, q.options FROM game_questions gq JOIN questions q
  if (/FROM game_questions gq\s+JOIN questions q/.test(s)) {
    const gameId = params[0];
    const rows = (store.gameQuestions.get(gameId) || []).map((q) => ({
      id: q.id,
      prompt: q.prompt,
      options: q.options,
    }));
    return { rows };
  }

  // questions SELECT
  if (/SELECT id, prompt, options FROM questions/.test(s)) {
    if (/ANY\(\$1::int\[\]\)/.test(s)) {
      const ids = params[0];
      const rows = ids.map((id) => {
        const q = store.questions.get(id);
        return q ? { id, prompt: q.prompt, options: q.options } : null;
      }).filter(Boolean);
      return { rows };
    }
    // seeded set in id order
    const rows = [...store.questions.entries()]
      .sort(([a], [b]) => a - b)
      .map(([id, q]) => ({ id, prompt: q.prompt, options: q.options }));
    return { rows };
  }

  // getGame: SELECT g.id, g.game_state, o.owner_user_id FROM games g LEFT JOIN ...
  if (/FROM games g\s+LEFT JOIN games_owners o/.test(s)) {
    const gameId = params[0];
    const game = store.games.get(gameId);
    if (!game) return { rows: [] };
    return {
      rows: [{ id: gameId, game_state: game.game_state, owner_user_id: store.owners.get(gameId) }],
    };
  }

  // submitAnswer: SELECT game_state FROM games WHERE id = $1 FOR UPDATE
  if (/SELECT game_state FROM games WHERE id = \$1 FOR UPDATE/.test(s)) {
    const gameId = params[0];
    const game = store.games.get(gameId);
    return game ? { rows: [{ game_state: game.game_state }] } : { rows: [] };
  }

  // SELECT owner_user_id FROM games_owners WHERE game_id = $1
  if (/SELECT owner_user_id FROM games_owners WHERE game_id = \$1/.test(s)) {
    const gameId = params[0];
    const owner = store.owners.get(gameId);
    return owner === undefined ? { rows: [] } : { rows: [{ owner_user_id: owner }] };
  }

  // transitionGame: SELECT game_state FROM games WHERE id = $1 FOR UPDATE (already handled)
  // answer: SELECT correct_answer FROM questions WHERE id = $1
  if (/SELECT correct_answer FROM questions WHERE id = \$1/.test(s)) {
    const q = store.questions.get(params[0]);
    return q ? { rows: [{ correct_answer: q.correct_answer }] } : { rows: [] };
  }

  // SELECT correct FROM answers WHERE game_id = $1 AND question_id = $2
  if (/SELECT correct FROM answers WHERE game_id = \$1 AND question_id = \$2/.test(s)) {
    const key = `${params[0]}:${params[1]}`;
    return store.answers.has(key)
      ? { rows: [{ correct: store.answers.get(key).correct }] }
      : { rows: [] };
  }

  // INSERT INTO answers
  if (/INSERT INTO answers \(game_id, question_id, answer, correct\)/.test(s)) {
    const key = `${params[0]}:${params[1]}`;
    store.answers.set(key, { answer: params[2], correct: params[3] });
    return { rows: [] };
  }

  // UPDATE games SET game_state = $1 WHERE id = $2
  if (/UPDATE games SET game_state = \$1 WHERE id = \$2/.test(s)) {
    store.games.set(params[1], { game_state: params[0] });
    return { rows: [] };
  }

  // computeScore / getScore: SELECT COUNT(*) ... FROM answers WHERE game_id = $1 AND correct = true
  if (/SELECT COUNT\(\*\)::int AS (correct_count|score) FROM answers/.test(s)) {
    const gameId = params[0];
    let count = 0;
    for (const [key, val] of store.answers.entries()) {
      const [gid] = key.split(':').map(Number);
      if (gid === gameId && val.correct) count += 1;
    }
    const col = /AS correct_count/.test(s) ? 'correct_count' : 'score';
    return { rows: [{ [col]: count }] };
  }

  throw new Error(`Unexpected SQL in fake: ${sql}`);
}

function seedQuestion(store, id, prompt, options, correctAnswer) {
  store.questions.set(id, { prompt, options, correct_answer: correctAnswer });
}

function setup() {
  const store = makeStore();
  seedQuestion(store, 1, '1/2 + 1/4 = ?', ['1/4', '3/4', '1/2'], '3/4');
  seedQuestion(store, 2, '2/3 of 6 = ?', ['3', '4', '5'], '4');
  const pool = makePgPool(store);
  return { store, pool };
}

test('newGame returns 201-shaped {id, questions} without correctAnswer', async () => {
  const { pool } = setup();
  const service = createGameService(pool);
  const result = await service.newGame(7, [1, 2]);
  assert.ok(Number.isInteger(result.id));
  assert.strictEqual(result.questions.length, 2);
  for (const q of result.questions) {
    assert.ok(q.id !== undefined);
    assert.ok(typeof q.prompt === 'string');
    assert.ok(Array.isArray(q.options));
    assert.strictEqual(q.correctAnswer, undefined);
  }
});

test('answer submits a correct answer and increments score by 1', async () => {
  const { pool } = setup();
  const service = createGameService(pool);
  const game = await service.newGame(7, [1]);
  const result = await service.answer(game.id, 1, '3/4', 7);
  assert.strictEqual(result.correct, true);
  assert.strictEqual(result.score, 1);
});

test('answer marks an incorrect answer without increasing score', async () => {
  const { pool } = setup();
  const service = createGameService(pool);
  const game = await service.newGame(7, [1]);
  const result = await service.answer(game.id, 1, '1/4', 7);
  assert.strictEqual(result.correct, false);
  assert.strictEqual(result.score, 0);
});

test('repeating a question does not increase the score (idempotent)', async () => {
  const { pool } = setup();
  const service = createGameService(pool);
  const game = await service.newGame(7, [1]);
  await service.answer(game.id, 1, '3/4', 7);
  const second = await service.answer(game.id, 1, '3/4', 7);
  assert.strictEqual(second.correct, true);
  assert.strictEqual(second.score, 1);

  const wrong = await service.answer(game.id, 1, '1/4', 7);
  // The stored "correct" result is preserved on a repeated answer.
  assert.strictEqual(wrong.correct, true);
  assert.strictEqual(wrong.score, 1);
});

test('pause then resume transitions state; answering while paused is a 409', async () => {
  const { pool } = setup();
  const service = createGameService(pool);
  const game = await service.newGame(7, [1]);

  const paused = await service.pauseGame(game.id, 7);
  assert.strictEqual(paused.state, States.PAUSED);

  await assert.rejects(
    () => service.answer(game.id, 1, '3/4', 7),
    (err) => err instanceof GameError && err.status === 409
  );

  const resumed = await service.resumeGame(game.id, 7);
  assert.strictEqual(resumed.state, States.PLAYING);

  const result = await service.answer(game.id, 1, '3/4', 7);
  assert.strictEqual(result.score, 1);
});

test('pause/resume/answer enforce owner authorization (403 for other users)', async () => {
  const { pool } = setup();
  const service = createGameService(pool);
  const game = await service.newGame(7, [1]);

  // pause as other user
  await assert.rejects(
    () => service.pauseGame(game.id, 99),
    (err) => err instanceof GameError && err.status === 403
  );

  // resume as other user
  await assert.rejects(
    () => service.resumeGame(game.id, 99),
    (err) => err instanceof GameError && err.status === 403
  );

  // answer as other user
  await assert.rejects(
    () => service.answer(game.id, 1, '3/4', 99),
    (err) => err instanceof GameError && err.status === 403
  );

  // score as other user
  await assert.rejects(
    () => service.viewScore(game.id, 99),
    (err) => err instanceof GameError && err.status === 403
  );

  // view game as other user
  await assert.rejects(
    () => service.viewGame(game.id, 99),
    (err) => err instanceof GameError && err.status === 403
  );
});

test('accessing a non-existent game returns 404', async () => {
  const { pool } = setup();
  const service = createGameService(pool);
  await assert.rejects(
    () => service.viewGame(9999, 7),
    (err) => err instanceof GameError && err.status === 404
  );
  await assert.rejects(
