'use strict';

const { test } = require('node:test');
const assert = require('node:assert');

const {
  FractionError,
  gcd,
  reduce,
  fromParts,
  parseFraction,
  equals,
  format,
} = require('../lib/fraction');

test('gcd returns the greatest common divisor of two integers', () => {
  assert.strictEqual(gcd(12, 18), 6);
  assert.strictEqual(gcd(18, 12), 6);
  assert.strictEqual(gcd(7, 5), 1);
  assert.strictEqual(gcd(0, 5), 5);
  assert.strictEqual(gcd(5, 0), 5);
  assert.strictEqual(gcd(-12, 18), 6);
  assert.strictEqual(gcd(0, 0), 0);
});

test('reduce normalizes sign so the denominator is always positive', () => {
  assert.deepStrictEqual(reduce(3, -4), { numerator: -3, denominator: 4 });
  assert.deepStrictEqual(reduce(-3, -4), { numerator: 3, denominator: 4 });
});

test('reduce produces a canonical reduced form', () => {
  assert.deepStrictEqual(reduce(2, 4), { numerator: 1, denominator: 2 });
  assert.deepStrictEqual(reduce(6, 8), { numerator: 3, denominator: 4 });
  assert.deepStrictEqual(reduce(0, 5), { numerator: 0, denominator: 1 });
});

test('reduce throws a typed error for a zero denominator', () => {
  assert.throws(
    () => reduce(1, 0),
    (err) => err instanceof FractionError && err.code === 'ZERO_DENOMINATOR'
  );
});

test('reduce throws a typed error for non-safe-integer parts', () => {
  assert.throws(
    () => reduce(1.5, 2),
    (err) => err instanceof FractionError && err.code === 'INVALID_FRACTION'
  );
  assert.throws(
    () => reduce('1', 2),
    (err) => err instanceof FractionError && err.code === 'INVALID_FRACTION'
  );
});

test('fromParts delegates to reduce', () => {
  assert.deepStrictEqual(fromParts(2, 4), { numerator: 1, denominator: 2 });
});

test('parseFraction accepts a plain fraction', () => {
  assert.deepStrictEqual(parseFraction('3/4'), { numerator: 3, denominator: 4 });
});

test('parseFraction normalizes fractional equality (2/4 === 1/2)', () => {
  assert.deepStrictEqual(parseFraction('2/4'), parseFraction('1/2'));
});

test('parseFraction accepts whole numbers as integer/1', () => {
  assert.deepStrictEqual(parseFraction('7'), { numerator: 7, denominator: 1 });
});

test('parseFraction accepts mixed numbers', () => {
  assert.deepStrictEqual(parseFraction('1 1/2'), { numerator: 3, denominator: 2 });
});

test('parseFraction accepts negative fractions', () => {
  assert.deepStrictEqual(parseFraction('-3/4'), { numerator: -3, denominator: 4 });
  assert.deepStrictEqual(parseFraction('3/-4'), { numerator: -3, denominator: 4 });
});

test('parseFraction accepts zero', () => {
  assert.deepStrictEqual(parseFraction('0/5'), { numerator: 0, denominator: 1 });
});

test('parseFraction rejects malformed input (empty, non-string, bad numeric)', () => {
  for (const bad of ['', 'abc', '1/2/3', '1/  ', '1/ 2/ 3']) {
    assert.throws(
      () => parseFraction(bad),
      (err) => err instanceof FractionError && err.code === 'INVALID_FRACTION',
      `expected "${bad}" to be rejected`
    );
  }
  assert.throws(
    () => parseFraction(5),
    (err) => err instanceof FractionError && err.code === 'INVALID_FRACTION'
  );
});

test('parseFraction rejects a zero denominator in string form', () => {
  assert.throws(
    () => parseFraction('1/0'),
    (err) => err instanceof FractionError && err.code === 'ZERO_DENOMINATOR'
  );
});

test('parseFraction rejects an improper mixed number fraction part', () => {
  assert.throws(
    () => parseFraction('1 3/2'),
    (err) => err instanceof FractionError && err.code === 'INVALID_FRACTION'
  );
});

test('equals compares canonical forms', () => {
  const a = fromParts(2, 4);
  const b = fromParts(1, 2);
  const c = fromParts(3, 4);
  assert.strictEqual(equals(a, b), true);
  assert.strictEqual(equals(a, c), false);
});

test('format renders canonical fractions readably', () => {
  assert.strictEqual(format(fromParts(3, 2)), '1 1/2');
  assert.strictEqual(format(fromParts(1, 2)), '1/2');
  assert.strictEqual(format(fromParts(4, 2)), '2');
  assert.strictEqual(format(fromParts(-3, 2)), '-1 1/2');
});

test('parseFraction accepts a single reduced fraction from seed-style input', () => {
  // Seed answers must be valid single fractions accepted by the same validator.
  const seeds = ['1/2', '3/4', '2/3', '5/8', '1/4'];
  for (const s of seeds) {
    const parsed = parseFraction(s);
    assert.ok(Number.isSafeInteger(parsed.numerator));
    assert.ok(parsed.denominator > 0);
  }
});

'use strict';

/**
 * Build-time verification script (npm run build).
 *
 * Performs real checks against the repository:
 *   - `node --check` (syntax validation) over every JavaScript source file
 *   - JSON.parse validation of JSON configuration files
 *   - YAML structure validation (openapi.yaml, compose.yaml, k8s manifest) via js-yaml
 *   - Presence/structure checks for OpenAPI and protobuf contracts
 *
 * This script never prints a success message in place of an actual check: every
 * assertion below either passes or throws, causing a non-zero exit code.
 */

const { execFileSync } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');
const yaml = require('js-yaml');

const ROOT = path.resolve(__dirname, '..');

const JS_FILES = [
  'gateway/app.js',
  'gateway/index.js',
  'lib/auth.js',
  'lib/cache.js',
  'lib/db.js',
  'lib/events.js',
  'lib/fraction.js',
  'lib/game-state.js',
  'lib/search.js',
  'lib/types.js',
  'lib/user-map.js',
  'public/app.js',
  'services/admin-service.js',
  'services/game-service.js',
  'services/question-service.js',
  'services/user-service.js',
  'test/auth.test.js',
  'test/fraction.test.js',
  'test/game-service.test.js',
  'test/integration.test.js',
];

const JSON_FILES = ['package.json', 'plan.json', 'traceability.json', 'keycloak/realm.json'];
const YAML_FILES = ['openapi.yaml', 'compose.yaml', 'k8s/spacefractions-deployment.yaml', 'reference/prometheus.yml'];

function assert(condition, message) {
  if (!condition) {
    throw new Error(message);
  }
}

function checkJs(file) {
  const abs = path.join(ROOT, file);
  assert(fs.existsSync(abs), `missing JavaScript source file: ${file}`);
  try {
    // --check only parses; no code is executed.
    execFileSync(process.execPath, ['--check', abs], { stdio: 'pipe' });
  } catch (err) {
    throw new Error(`syntax error in ${file}: ${err.message}`);
  }
}

function checkJson(file) {
  const abs = path.join(ROOT, file);
  assert(fs.existsSync(abs), `missing JSON file: ${file}`);
  const raw = fs.readFileSync(abs, 'utf8');
  try {
    JSON.parse(raw);
  } catch (err) {
    throw new Error(`invalid JSON in ${file}: ${err.message}`);
  }
}

function checkYaml(file) {
  const abs = path.join(ROOT, file);
  assert(fs.existsSync(abs), `missing YAML file: ${file}`);
  const raw = fs.readFileSync(abs, 'utf8');
  try {
    yaml.load(raw);
  } catch (err) {
    throw new Error(`invalid YAML in ${file}: ${err.message}`);
  }
}

function checkOpenApi() {
  const abs = path.join(ROOT, 'openapi.yaml');
  const doc = yaml.load(fs.readFileSync(abs, 'utf8'));
  assert(doc, 'openapi.yaml parsed to empty document');
  assert(doc.openapi && typeof doc.openapi === 'string', 'openapi.yaml missing openapi version');
  assert(doc.info, 'openapi.yaml missing info');
  assert(doc.paths && typeof doc.paths === 'object', 'openapi.yaml missing paths');
  assert('/health' in doc.paths, 'openapi.yaml missing GET /health contract');
  assert('/play' in doc.paths, 'openapi.yaml missing GET /play backward-compat contract');
}

function checkProto() {
  const abs = path.join(ROOT, 'internal.proto');
  assert(fs.existsSync(abs), 'missing internal.proto');
  const raw = fs.readFileSync(abs, 'utf8');
  assert(raw.includes('service GameService'), 'internal.proto missing GameService');
  assert(raw.includes('rpc Play'), 'internal.proto missing Play rpc');
}

function main() {
  for (const file of JS_FILES) checkJs(file);
  for (const file of JSON_FILES) checkJson(file);
  for (const file of YAML_FILES) checkYaml(file);
  checkOpenApi();
  checkProto();
  process.stdout.write('build check passed: sources, configs and contracts verified\n');
}

try {
  main();
} catch (err) {
  process.stderr.write(`build check failed: ${err.message}\n`);
  process.exitCode = 1;
}

