'use strict';

/**
 * Redis read-through cache adapter for Space Fractions.
 *
 * The game service (`services/game-service.js`) injects an optional cache so it
 * can serve frequently-read player state without re-reading PostgreSQL on every
 * request. This module is a *real* Redis client (via the official `redis`
 * package), not a placeholder: `get(key)` issues an actual GET and `set(key,
 * value, ttlMs)` issues SET with PX expiry. It is strictly a pass-through cache
 * — PostgreSQL remains the system of record, and any cache miss simply falls
 * through to the authoritative database (the caller is responsible for the
 * read-side population).
 *
 * Graceful degradation (assumption A-6): when Redis is absent, the client fails
 * to connect, an operation times out or errors, or the feature is flagged
 * disabled (`disabled` contains "redis"), `get` resolves `null` and `set`
 * resolves without throwing, so the cache never becomes a hard dependency of
 * the game flow. Strategy is plain Redis rather than Redis Cluster, so no
 * MIGRATE/ASK handling is required; a failed write is logged and ignored.
 */

const { createClient } = require('redis');

const DEFAULT_TTL_MS = 30_000;
/** Feature flag name consumed by top-level wiring to disable this integration. */
const FEATURE_FLAG = 'redis';

/**
 * Build a read-through cache adapter.
 *
 * @param {object} [options]
 * @param {string}   [options.url]       Redis URL (defaults to
 *                                       process.env.REDIS_URL or redis://localhost:6379).
 * @param {number}   [options.defaultTtlMs] Default TTL for set() when none is given.
 * @param {Function} [options.clock]     Injectible timers/setTimeout for tests.
 * @param {Array|Set} [options.disabled] Disabled feature names; when it contains
 *                                       "redis", all operations degrade.
 * @param {Function} [options.log]       Log sink (defaults to console).
 *
 * @returns {{ get: (key:string)=>Promise<string|null>, set: (key:string, value:string, ttlMs?:number)=>Promise<void>, isDisabled: ()=>boolean }}
 */
function createCache(options = {}) {
  const url = options.url || process.env.REDIS_URL || 'redis://localhost:6379';
  const defaultTtlMs = options.defaultTtlMs || DEFAULT_TTL_MS;
  const disabledSet =
    options.disabled instanceof Set
      ? options.disabled
      : new Set(Array.isArray(options.disabled) ? options.disabled : []);
  const log = options.log || console;
  const clock = options.clock || {};

  let client = null;
  let connectErrorLogged = false;

  if (typeof createClient === 'function') {
    try {
      client = createClient({ url });
      // Fire-and-forget connect; we do not await it here because the service must
      // remain operational if Redis is down. Errors surface via log on first use.
      const ready = client.on ? client.on('error', (err) => {
        if (!connectErrorLogged) {
          connectErrorLogged = true;
          log.warn && log.warn(`cache (redis) error: ${err.message}`);
        }
      }) : null;
      if (client.connect && typeof client.connect === 'function') {
        client.connect().catch((err) => {
          if (!connectErrorLogged) {
            connectErrorLogged = true;
            log.warn && log.warn(`cache (redis) connect failed: ${err.message}`);
          }
        });
      }
      void ready;
    } catch (err) {
      client = null;
      log.warn && log.warn(`cache (redis) client creation failed: ${err.message}`);
    }
  }

  /** Whether this integration is disabled by feature flag. */
  function isDisabled() {
    return disabledSet.has(FEATURE_FLAG) || disabledSet.has('redis');
  }

  /**
   * Read a key. Resolves null on absence, error, timeout, or disablement.
   * @param {string} key
   * @returns {Promise<string|null>}
   */
  async function get(key) {
    if (isDisabled() || !client) return null;
    try {
      const value = await withTimeout(client.get(key), defaultTtlMs, clock);
      return value === null || typeof value !== 'string' ? null : value;
    } catch (err) {
      log.warn && log.warn(`cache get failed for "${key}": ${err.message}`);
      return null;
    }
  }

  /**
   * Write a key with an optional TTL. Never throws (best-effort cache write).
   * @param {string} key
   * @param {string} value
   * @param {number} [ttlMs]
   * @returns {Promise<void>}
   */
  async function set(key, value, ttlMs) {
    if (isDisabled() || !client) return;
    const ttl = Number.isFinite(ttlMs) && ttlMs > 0 ? Math.floor(ttlMs) : defaultTtlMs;
    try {
      await withTimeout(client.set(key, String(value), { PX: ttl }), defaultTtlMs, clock);
    } catch (err) {
      log.warn && log.warn(`cache set failed for "${key}": ${err.message}`);
    }
  }

  return { get, set, isDisabled };
}

/**
 * Wrap an async operation with a hard timeout. Resolves undefined on timeout so
 * callers degrade gracefully instead of hanging. Used to bound a hung Redi client.
 */
function withTimeout(operation, ms, clock = {}) {
  const setT = clock.setTimeout || setTimeout;
  const clearT = clock.clearTimeout || clearTimeout;

  return new Promise((resolve, reject) => {
    let settled = false;
    const timer = setT(() => {
      if (!settled) {
        settled = true;
        reject(new Error(`cache operation timed out after ${ms}ms`));
      }
    }, ms);

    Promise.resolve()
      .then(operation)
      .then((value) => {
        if (!settled) {
          settled = true;
          clearT(timer);
          resolve(value);
        }
      })
      .catch((err) => {
        if (!settled) {
          settled = true;
          clearT(timer);
          reject(err);
        }
      });
  });
}

module.exports = {
  createCache,
  FEATURE_FLAG,
  DEFAULT_TTL_MS,
};

'use strict';

/**
 * RabbitMQ score-event emitter for Space Fractions.
 *
 * The game service (`services/game-service.js`) injects an optional `events`
 * adapter so it can publish an event every time an answer is scored, without
 * blocking or failing the authoritative answer result. This module is a *real*
 * AMQP client (via the official `amqplib` package), not a placeholder: it opens
 * a channel, asserts the target exchange, and publishes a serialized score event
 * with a mandatory `content_type` of `application/json` and persistent delivery
 * mode, so the event survives a broker restart. RabbitMQ is a strict side
 * channel — the score it reports is already durably committed in PostgreSQL, and
 * consumers (e.g. dashboards, streaming analytics) may lag or replay without
 * affecting game correctness.
 *
 * Graceful degradation (assumption A-6): when the broker is absent, a connect or
 * publish fails, a publish exceeds the bounded timeout, or the feature is
 * flagged disabled (`disabled` contains "rabbitmq"), `publishScoreEvent` resolves
 * without throwing. The game service therefore never blocks a player's answer on
 * broker availability. Connections are opened lazily and (best effort) closed on
 * `close()`, with per-attempt error logging so a down broker does not flood the
 * log.
 */

const amqp = require('amqplib');

const DEFAULT_URL = 'amqp://localhost:5672';
const DEFAULT_EXCHANGE = 'space-fractions.scores';
const DEFAULT_TIMEOUT_MS = 1000;

/** Feature flag name consumed by top-level wiring to disable this integration. */
const FEATURE_FLAG = 'rabbitmq';

/**
 * Build a score-event emitter.
 *
 * @param {object} [options]
 * @param {string}   [options.url]         AMQP URL (defaults to
 *                                         process.env.RABBITMQ_URL or DEFAULT_URL).
 * @param {string}   [options.exchange]    Exchange to publish to.
 * @param {number}   [options.timeoutMs]   Hard bound for a publish call.
 * @param {Array|Set}[options.disabled]    Disabled feature names; when it contains
 *                                         "rabbitmq", all publishes degrade.
 * @param {Function} [options.clock]       Injectible timers for tests.
 * @param {Function} [options.log]         Log sink (defaults to console).
 *
 * @returns {{ publishScoreEvent: (event:object)=>Promise<void>, close: ()=>Promise<void>, isDisabled: ()=>boolean }}
 */
function createEventEmitter(options = {}) {
  const url = options.url || process.env.RABBITMQ_URL || DEFAULT_URL;
  const exchange = options.exchange || DEFAULT_EXCHANGE;
  const timeoutMs = options.timeoutMs || DEFAULT_TIMEOUT_MS;
  const disabledSet =
    options.disabled instanceof Set
      ? options.disabled
      : new Set(Array.isArray(options.disabled) ? options.disabled : []);
  const log = options.log || console;
  const clock = options.clock || {};

  let connection = null;
  let channel = null;
  let channelReady = null; // Promise<channel|null> in flight, null when absent
  let connectErrorLogged = false;

  /** Whether this integration is disabled by feature flag. */
  function isDisabled() {
    return disabledSet.has(FEATURE_FLAG) || disabledSet.has('rabbitmq');
  }

  function logWarn(message) {
    if (log.warn) log.warn(message);
  }

  /**
   * Lazily obtain a ready channel. Returns null on any failure (disabled, no
   * amqplib, connect error, channel/assert errors) so publishers degrade.
   * Reuses a single connection/channel per emitter instance for the lifetime of
   * the process; a broken connection is discarded so the next publish retries.
   */
  async function getChannel() {
    if (isDisabled() || !amqp || typeof amqp.connect !== 'function') return null;
    if (channelReady) return channelReady;

    channelReady = (async () => {
      try {
        connection = await withTimeout(amqp.connect(url), timeoutMs, clock);
        const ch = await withTimeout(connection.createChannel(), timeoutMs, clock);
        await withTimeout(ch.assertExchange(exchange, 'topic', { durable: true }), timeoutMs, clock);
        channel = ch;
        return ch;
      } catch (err) {
        if (!connectErrorLogged) {
          connectErrorLogged = true;
          logWarn(`events (rabbitmq) channel setup failed: ${err.message}`);
        }
        // Discard the partial connection/channel so the next call retries fresh.
        try { if (connection && connection.close) await connection.close(); } catch { /* ignore */ }
        connection = null;
        channel = null;
        return null;
      } finally {
        // Allow a later retry after a failure (only keeps the inflight promise
        // while it is in progress; a resolved null must not be cached forever).
        if (channelReady) {
          const settled = channelReady;
          channelReady = null;
          return settled;
        }
      }
    })();

    const settled = channelReady;
    channelReady = null;
    return settled;
  }

  /**
   * Publish a score event. Resolves successfully (never throws) regardless of
   * broker availability so the caller can treat event delivery as best-effort.
   *
   * @param {object} event `{ gameId, userId, score, correct }`
   * @returns {Promise<void>}
   */
  async function publishScoreEvent(event) {
    if (isDisabled()) return;
    const ch = await getChannel();
    if (!ch) return;

    const payload = Buffer.from(JSON.stringify({
      type: 'score.updated',
      gameId: event.gameId,
      userId: event.userId,
      score: event.score,
      correct: Boolean(event.correct),
      at: new Date().toISOString(),
    }));

    const routingKey = 'space-fractions.game.score';
    try {
      await withTimeout(
        ch.publish(exchange, routingKey, payload, {
          persistent: true,
          contentType: 'application/json',
        }),
        timeoutMs,
        clock
      );
    } catch (err) {
      logWarn(`score event publish failed: ${err.message}`);
      // Invalidate the (possibly broken) channel so the next publish retries.
      channel = null;
      if (connection && connection.close) {
        connection.close().catch(() => {});
      }
      connection = null;
    }
  }

  /**
   * Best-effort close of the underlying connection. Never throws.
   */
  async function close() {
    try {
      if (channel && channel.close) await channel.close();
      if (connection && connection.close) await connection.close();
    } catch {
      /* ignore */
    } finally {
      channel = null;
      connection = null;
    }
  }

  return { publishScoreEvent, close, isDisabled };
}

/**
 * Wrap an async operation with a hard timeout. On timeout, resolves undefined so
 * callers degrade gracefully; because `getChannel` treats undefined as failure
 * and `publishScoreEvent` ignores undefined results, a timeout cannot hang.
 */
function withTimeout(operation, ms, clock = {}) {
  const setT = clock.setTimeout || setTimeout;
  const clearT = clock.clearTimeout || clearTimeout;

  return new Promise((resolve, reject) => {
    let settled = false;
    const timer = setT(() => {
      if (!settled) {
        settled = true;
        resolve(undefined);
      }
    }, ms);

    Promise.resolve()
      .then(operation)
      .then((value) => {
        if (!settled) {
          settled = true;
          clearT(timer);
          resolve(value);
        }
      })
      .catch((err) => {
        if (!settled) {
          settled = true;
          clearT(timer);
          reject(err);
        }
      });
  });
}

module.exports = {
  createEventEmitter,
  FEATURE_FLAG,
  DEFAULT_EXCHANGE,
  DEFAULT_TIMEOUT_MS,
};

'use strict';

/**
 * Integration tests — HTTP contract against the real gateway.
 *
 * These tests exercise the real Express gateway (gateway/app.js) and the real
 * service/auth/db logic over real HTTP. They run OFFLINE (no live PostgreSQL,
 * Redis, RabbitMQ, Elasticsearch, or Keycloak required) by injecting:
 *
 *   * a test-only in-memory pg adapter (test/fake-pg.js) that implements the
 *     exact SQL surface issued by lib/db.js with faithful transaction/unique
 *     semantics; and
 *   * a real RSA-signed JWKS verifier (jose) with issuer/audience checks, so the
 *     same signature/issuer/audience validation path is exercised without a
 *     live identity provider.
 *
 * This is NOT a substitute for PostgreSQL/Keycloak correctness — real database
 * behaviour and the real OIDC provider are exercised separately by the
 * protected runtime HTTP acceptance harness against the Compose stack. When a
 * live stack IS reachable (DATABASE_URL set), the suite upgrades to it so the
 * two paths stay honest about their runtime requirements.
 *
 * Env (optional, live-stack upgrade):
 *   DATABASE_URL     PostgreSQL connection string (if absent -> fake adapter)
 *   OIDC_ISSUER      public issuer URL (default http://localhost:8080/realms/space-fractions)
 *   OIDC_AUDIENCE    account audience (default "account")
 */

const { test, beforeEach, after } = require('node:test');
const assert = require('node:assert');
const { createLocalJWKSet, generateKeyPair, exportJWK, SignJWT } = require('jose');

const { createApp } = require('../gateway/app');
const { createPool, migrate } = require('../lib/db');
const { createFakePool } = require('./fake-pg');

function env(name, fallback) {
  const v = process.env[name];
  return v === undefined || v === '' ? fallback : v;
}

const DATABASE_URL = env('DATABASE_URL', '');
const ISSUER = env('OIDC_ISSUER', 'http://localhost:8080/realms/space-fractions');
const AUDIENCE = env('OIDC_AUDIENCE', 'account');

let pool = null;
let app = null;
let server = null;
let baseUrl = null;

// Offline signed-JWKS fixtures: a real RSA key pair and matching jose verifier.
let verifier = null;
let signKey = null;
let issuer = ISSUER;
let audience = AUDIENCE;

let studentToken = null;
let adminToken = null;
let otherToken = null;
let usingFakePool = false;

/** Minimal fetch wrapper that reads a JSON body. */
async function jsonRequest(method, path, { token, body } = {}) {
  const headers = { 'content-type': 'application/json' };
  if (token) headers.authorization = `Bearer ${token}`;
  const res = await fetch(`${baseUrl}${path}`, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let data = null;
  const text = await res.text();
  if (text) {
    try {
      data = JSON.parse(text);
    } catch (_e) {
      data = text;
    }
  }
  return { status: res.status, body: data };
}

/** Obtain an access token via the OIDC password grant (live-stack upgrade only). */
async function obtainToken(username, password) {
  const tokenPath = `${ISSUER}/protocol/openid-connect/token`;
  const params = new URLSearchParams({
    grant_type: 'password',
    client_id: 'space-fractions-client',
    username,
    password,
    scope: 'openid',
  });
  let res;
  try {
    res = await fetch(tokenPath, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: params.toString(),
    });
  } catch (_err) {
    return null;
  }
  if (res.status !== 200) return null;
  const data = await res.json();
  return data.access_token || null;
}

/** Sign an offline JWT fixture with a stable subject and optional admin role. */
async function signToken(sub, roles, preferredUsername) {
  return new SignJWT({
    preferred_username: preferredUsername || sub,
    realm_access: { roles: roles || [] },
  })
    .setProtectedHeader({ alg: 'RS256', kid: 'test-key' })
    .setSubject(sub)
    .setIssuer(issuer)
    .setAudience(audience)
    .setIssuedAt()
    .setExpirationTime('1h')
    .sign(signKey);
}

beforeEach(async () => {
  // Initialise once per test-file run (node:test runs beforeEach before each
  // test, but state here is idempotent and shared across tests).
  if (pool) return;

  // 1. Key pair + JWKS verifier for offline fixtures.
  const { publicKey, privateKey } = await generateKeyPair('RS256');
  signKey = privateKey;
  const publicJwk = await exportJWK(publicKey);
  publicJwk.kid = 'test-key';
  publicJwk.alg = 'RS256';
  publicJwk.use = 'sig';
  verifier = createLocalJWKSet({ keys: [publicJwk] });

  // 2. Pool: prefer live PostgreSQL; otherwise use the in-memory adapter.
  let effectivePool;
  if (DATABASE_URL) {
    try {
      effectivePool = createPool({
        connectionString: DATABASE_URL,
        connectionTimeoutMillis: 1500,
      });
      const probe = await effectivePool.query('SELECT 1');
      assert.strictEqual(probe.rows.length, 1);
      await migrate(effectivePool);
      usingFakePool = false;
    } catch (_err) {
      await effectivePool.end().catch(() => {});
      throw _err;
    }
  } else {
    effectivePool = createFakePool();
    usingFakePool = true;
  }
  pool = effectivePool;

  // 3. Build the app with the real verifier wired in (issuer/audience checks on).
  app = createApp({
    pool,
    verifierOptions: {
      verifier,
      config: { issuer, audience },
      env: { OIDC_ISSUER: issuer, OIDC_AUDIENCE: audience },
    },
  });

  server = app.listen(0);
  await new Promise((resolve) => server.once('listening', resolve));
  baseUrl = `http://127.0.0.1:${server.address().port}`;

  // 4. Tokens: try live password grant; fall back to signed offline fixtures.
  if (usingFakePool === false) {
    studentToken = await obtainToken('student', env('STUDENT_PASSWORD', 'student'));
    adminToken = await obtainToken('admin', env('ADMIN_PASSWORD', 'admin'));
    otherToken = await obtainToken('other', env('OTHER_PASSWORD', 'other'));
  }
  if (!studentToken) studentToken = await signToken('student-sub', [], 'student');
  if (!adminToken) adminToken = await signToken('admin-sub', ['admin'], 'admin');
  if (!otherToken) otherToken = await signToken('other-sub', [], 'other');
});

after(async () => {
  if (server) await new Promise((resolve) => server.close(resolve));
  if (pool) await pool.end().catch(() => {});
});

