/**
 * Bound a promise to a timeout, resolving the fallback (undefined) rather than
 * throwing so callers can degrade gracefully.
 */
function withTimeout(promise, ms) {
  return new Promise((resolve) => {
    let done = false;
    const timer = setTimeout(() => {
      if (!done) {
        done = true;
        resolve(undefined);
      }
    }, ms);
    promise
      .then((val) => {
        if (!done) {
          done = true;
          clearTimeout(timer);
          resolve(val);
        }
      })
      .catch(() => {
        if (!done) {
          done = true;
          clearTimeout(timer);
          resolve(undefined);
        }
      });
  });
}

