  const m = sql.match(/^UPDATE\s+([a-zA-Z0-9_]+)\s+SET\s+([a-zA-Z0-9_]+)\s*=\s*\$(\d+)\s+WHERE\s+([a-zA-Z0-9_]+)\s*=\s*\$(\d+)/i);
  if (!m) throw new Error(`fake-pg: cannot parse UPDATE: ${sql}`);
