'use strict';

/**
 * Question service: admin CRUD, stable ordering, and player-safe projection.
 *
 * Responsibilities (Architecture_Documentation.md §D "QuestionComponent" and the
 * operator acceptance contract, space-fractions.md 19-31):
 *
 *   * Admin-owned question storage backed by the `questions` table (PostgreSQL).
 *   * Stable question ordering (deterministic ORDER BY id).
 *   * Never include `correctAnswer` in a player-facing response; the correct
 *     answer key is only ever returned on the authenticated admin endpoints.
 *   * Optional Elasticsearch-backed search with a bounded timeout. The search
 *     client is injected so the module remains unit-testable without live
 *     infrastructure and degrades gracefully (authoritative DB fallback) when
 *     the search backend is absent or unavailable.
 *
 * Authorization is NOT enforced here. The owning admin route (services/admin-
 * service.js) performs the `requireRole('admin')` gate before delegating to this
 * module, per the acceptance contract (normal users -> 403 at the route layer).
 */

const { withTransaction, DbError } = require('../lib/db');
const { parseFraction } = require('../lib/fraction');

/** Default bounded timeout for downstream search calls (milliseconds). */
const DEFAULT_SEARCH_TIMEOUT_MS = 500;

/**
 * Error type for question-domain failures. `status` maps to an HTTP status code
 * so route handlers can propagate typed errors without inspecting SQL codes.
 */
class QuestionError extends Error {
  constructor(message, code, status) {
    super(message);
    this.name = 'QuestionError';
    this.code = code || 'QUESTION_ERROR';
    this.status = status || 400;
  }
}

/**
 * Validate a question payload before it is written.
 *
 *   prompt       -> non-empty string
 *   options      -> array of strings (at least one option)
 *   correctAnswer -> parseable single reduced fraction (server-side validation)
 *
 * Throws QuestionError (status 400) on any violation.
 */
function validateQuestion({ prompt, options, correctAnswer }) {
  if (typeof prompt !== 'string' || prompt.trim() === '') {
    throw new QuestionError('prompt must be a non-empty string', 'INVALID_PROMPT', 400);
  }
  if (!Array.isArray(options) || options.length === 0) {
    throw new QuestionError('options must be a non-empty array', 'INVALID_OPTIONS', 400);
  }
  for (const opt of options) {
    if (typeof opt !== 'string') {
      throw new QuestionError('each option must be a string', 'INVALID_OPTIONS', 400);
    }
  }
  if (typeof correctAnswer !== 'string' || correctAnswer.trim() === '') {
    throw new QuestionError('correctAnswer must be a non-empty string', 'INVALID_ANSWER', 400);
  }
  // Enforce the exact-rational-arithmetic contract at the boundary.
  try {
    parseFraction(correctAnswer);
  } catch (fractionErr) {
    throw new QuestionError(
      `correctAnswer is not a valid reduced fraction: ${fractionErr.message}`,
      'INVALID_ANSWER',
      400
    );
  }
}

/**
 * Convert a `questions` table row into the admin-facing shape.
 * Includes correctAnswer (callers must be behind the admin authorization gate).
 */
function toAdminQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: typeof row.options === 'string' ? JSON.parse(row.options) : row.options,
    correctAnswer: row.correct_answer,
  };
}

/**
 * Convert a `questions` table row into the player-facing shape.
 * NEVER includes correctAnswer.
 */
function toPublicQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: typeof row.options === 'string' ? JSON.parse(row.options) : row.options,
  };
}

/**
 * Build the question service over a `pg` pool and an optional search backend.
 *
 * `searchClient` is an adapter implementing:
 *   search(query) -> Promise<Array<{id, prompt}>>  (already public-safe)
 * `searchTimeoutMs` bounds the downstream call; on timeout or backend failure we
 * fall back to a database LIKE query so search remains authoritative and correct
 * even when Elasticsearch is unavailable.
 *
 * The returned methods never surface `correct_answer` unless explicitly part of
 * the admin contract.
 */
function createQuestionService(pool, { searchClient = null, searchTimeoutMs = DEFAULT_SEARCH_TIMEOUT_MS } = {}) {
  /**
   * Create a question. Returns the admin projection (including correctAnswer).
   */
  async function createQuestion(input) {
    validateQuestion(input);
    const optionsJson = JSON.stringify(input.options);
    const result = await pool.query(
      `INSERT INTO questions (prompt, options, correct_answer)
       VALUES ($1, $2, $3)
       RETURNING id, prompt, options, correct_answer`,
      [input.prompt.trim(), optionsJson, formatCorrectAnswer(input.correctAnswer)]
    );
    return toAdminQuestion(result.rows[0]);
  }

  /**
   * List all questions in stable (id) order. Returns the admin projection:
   * { questions: [{ id, prompt, options, correctAnswer }] }.
   */
  async function listQuestions() {
    const result = await pool.query(
      `SELECT id, prompt, options, correct_answer
         FROM questions
        ORDER BY id`
    );
    return { questions: result.rows.map(toAdminQuestion) };
  }

  /**
   * List questions in the public (player-facing) shape, stable id order, never
   * including correctAnswer.
   */
  async function listPublicQuestions() {
    const result = await pool.query(
      `SELECT id, prompt, options
         FROM questions
        ORDER BY id`
    );
    return result.rows.map(toPublicQuestion);
  }

  /**
   * Fetch a single public question (no correctAnswer). Returns null if missing.
   */
  async function getPublicQuestion(id) {
    const result = await pool.query(
      `SELECT id, prompt, options FROM questions WHERE id = $1`,
      [id]
    );
    return result.rows.length ? toPublicQuestion(result.rows[0]) : null;
  }

  /**
   * Delete a question by id. Returns true when a row was deleted, false when no
   * such question existed.
   */
  async function deleteQuestion(id) {
    const result = await pool.query(
      `DELETE FROM questions WHERE id = $1 RETURNING id`,
      [id]
    );
    return result.rows.length > 0;
  }

  /**
   * Search questions by a plain-text query.
   *
   * Prefers the injected Elasticsearch client with a bounded timeout; on any
   * failure (absence, timeout, error) it falls back to an authoritative DB
   * `ILIKE` search so search never returns stale/empty results silently. Results
   * are always the public projection (no correctAnswer).
   */
  async function searchQuestions(query) {
    if (typeof query !== 'string' || query.trim() === '') {
      return [];
    }
    const term = query.trim();

    if (searchClient && typeof searchClient.search === 'function') {
      const result = await withTimeout(
        Promise.resolve(searchClient.search(term)),
        searchTimeoutMs
      );
      if (result && Array.isArray(result.matched)) {
        return result.matched.map((q) => toPublicQuestion(q));
      }
    }

    // Authoritative DB fallback (bounded to id order for stable results).
    const dbResult = await pool.query(
      `SELECT id, prompt, options
         FROM questions
        WHERE prompt ILIKE $1
        ORDER BY id`,
      [`%${escapeLike(term)}%`]
    );
    return dbResult.rows.map(toPublicQuestion);
  }

  return {
    createQuestion,
    listQuestions,
    listPublicQuestions,
    getPublicQuestion,
    deleteQuestion,
    searchQuestions,
  };
}

/**
 * Normalize a correct answer to the canonical single reduced fraction string so
 * the stored value always satisfies the DB CHECK constraint and the same
 * validator used at runtime. Preserves original sign/whole-number forms but
 * reduces where possible (e.g. "2/4" -> "1/2").
 */
function formatCorrectAnswer(answer) {
  const f = parseFraction(answer);
  // Re-render via reduce to guarantee reduced gcd = 1 form ("n/d").
  return `${f.numerator}/${f.denominator}`;
}

/** Escape `%`/`_` so an ILIKE pattern matches the literal term only. */
function escapeLike(term) {
  return term.replace(/[\\%_]/g, (c) => `\\${c}`);
}

/**
 * Bound a promise to a timeout, resolving the fallback (undefined) rather than
 * throwing so callers can degrade gracefully.
 */
function withTimeout(promise, ms) {
  return new Promise((resolve) => {
    let done = false;
    const timer = setTimeout(() => {
      if (!done) {
        done = true;
        resolve(undefined);
      }
    }, ms);
    promise
      .then((val) => {
        if (!done) {
          done = true;
          clearTimeout(timer);
          resolve(val);
        }
      })
      .catch(() => {
        if (!done) {
          done = true;
          clearTimeout(timer);
          resolve(undefined);
        }
      });
  });
}

module.exports = {
  QuestionError,
  validateQuestion,
  toAdminQuestion,
  toPublicQuestion,
  createQuestionService,
  DEFAULT_SEARCH_TIMEOUT_MS,
};

'use strict';

/**
 * Game lifecycle state machine for Space Fractions.
 *
 * Mirrors the state diagram in Architecture_View.md:
 *   [*] --> Playing
 *   Playing --> Paused : pause()
 *   Paused --> Playing : resume()
 *   Playing --> GameOver : gameOver()
 *
 * Only these transitions are permitted; attempting an invalid transition throws
 * a typed GameStateError so callers can translate it into an HTTP status
 * (e.g. answering while paused -> 409, acting on a finished game -> 409).
 */

/**
 * Canonical state values. Allowed transitions:
 *   Playing -> Paused  (pause)
 *   Paused  -> Playing (resume)
 *   Playing -> GameOver (gameOver)
 */
const States = Object.freeze({
  PLAYING: 'Playing',
  PAUSED: 'Paused',
  GAME_OVER: 'GameOver',
});

class GameStateError extends Error {
  constructor(message, code) {
    super(message);
    this.name = 'GameStateError';
    this.code = code || 'INVALID_TRANSITION';
  }
}

/**
 * Create a fresh game in the Playing state.
 */
function initialState() {
  return { state: States.PLAYING };
}

/**
 * Validate that a raw value represents a known state.
 * Returns the canonical state string or throws GameStateError.
 */
function normalize(state) {
  if (state === undefined || state === null) {
    return States.PLAYING;
  }
  if (!Object.values(States).includes(state)) {
    throw new GameStateError(`Unknown game state: ${String(state)}`, 'INVALID_STATE');
  }
  return state;
}

/**
 * Attempt the pause transition.
 * Allowed only from Playing.
 */
function pause(current) {
  const s = normalize(typeof current === 'string' ? current : current && current.state);
  if (s !== States.PLAYING) {
    throw new GameStateError(
      `Cannot pause from state "${s}"`,
      s === States.GAME_OVER ? 'GAME_OVER' : 'INVALID_TRANSITION'
    );
  }
  return { state: States.PAUSED };
}

/**
 * Attempt the resume transition.
 * Allowed only from Paused.
 */
function resume(current) {
  const s = normalize(typeof current === 'string' ? current : current && current.state);
  if (s !== States.PAUSED) {
    throw new GameStateError(
      `Cannot resume from state "${s}"`,
      s === States.GAME_OVER ? 'GAME_OVER' : 'INVALID_TRANSITION'
    );
  }
  return { state: States.PLAYING };
}

/**
 * Attempt the gameOver transition.
 * Allowed only from Playing.
 */
function gameOver(current) {
  const s = normalize(typeof current === 'string' ? current : current && current.state);
  if (s !== States.PLAYING) {
    throw new GameStateError(
      `Cannot end game from state "${s}"`,
      s === States.GAME_OVER ? 'GAME_OVER' : 'INVALID_TRANSITION'
    );
  }
  return { state: States.GAME_OVER };
}

/**
 * Whether the game currently accepts answers (must be Playing).
 */
function isPlayable(current) {
  const s = normalize(typeof current === 'string' ? current : current && current.state);
  return s === States.PLAYING;
}

module.exports = {
  States,
  GameStateError,
  initialState,
  normalize,
  pause,
  resume,
  gameOver,
  isPlayable,
};

'use strict';

/**
 * Gateway HTTP entrypoint: Express application wiring the question, game, user,
 * and admin service modules into a single process with multiple service
 * entrypoint modules behind it.
 *
 * Contract (space-fractions.md 15-18):
 *   * GET /health -> 200.
 *   * Browser UI served at / (static files from public/).
 *   * Authenticated endpoints use Bearer OIDC access tokens; missing/invalid
 *     credentials -> 401; a verified non-admin user hitting an admin endpoint
 *     -> 403.
 *   * Original GET /play returns gameId for backward compatibility
 *     (Architecture_Documentation.md 81-103).
 *   * Admin question CRUD, game lifecycle, scoring, pause/resume, and search
 *     are exposed under /api via the injected service modules.
 *   * /metrics serves Prometheus metrics (real prom-client registry, not a
 *     placeholder), and question search uses the real Elasticsearch client via
 *     services/question-service.js.
 *
 * All infrastructure (pg pool, cache, events, search, verifier) is injected so
 * this module is unit-testable without live infrastructure; callers construct a
 * ready app via createApp(...). The process bootstrap lives in gateway/index.js.
 */

const path = require('node:path');
const express = require('express');

const { authenticate, AuthError } = require('../lib/auth');
const { createAdminService } = require('../services/admin-service');
const { createGameService, GameError } = require('../services/game-service');
const { createQuestionService, QuestionError } = require('../services/question-service');
const { createUserService, UserError } = require('../services/user-service');

/**
 * Build the Express application.
 *
 * @param {object} deps
 * @param {object} deps.pool             pg pool (lib/db.js) — required.
 * @param {object} [deps.cache]          cache adapter (lib/cache.js) — optional.
 * @param {object} [deps.events]         score-event emitter (lib/events.js) — optional.
 * @param {object} [deps.searchClient]   Elasticsearch adapter (lib/search.js) — optional.
 * @param {object} [deps.metrics]        prom-client registry with `metrics()` async — optional.
 * @param {object} [deps.verifierOptions]  options passed to lib/auth.authenticate (verifier/env/config) — optional.
 * @param {boolean} [deps.requireAuth]    when true, /play and game endpoints require auth (default true).
 */
function createApp({
  pool,
  cache = null,
  events = null,
  searchClient = null,
  metrics = null,
  verifierOptions = null,
  requireAuth = true,
} = {}) {
  if (!pool) {
    throw new Error('createApp requires a pg pool');
  }

  const app = express();
  app.use(express.json());

  const questionService = createQuestionService(pool, { searchClient });
  const gameService = createGameService(pool, {
    cache,
    events,
    questionService,
  });
  const userService = createUserService(pool);
  const adminService = createAdminService(pool, { questionService });

  /**
   * Resolve a verified authentication context from the request, or 401.
   * Attaches { payload, userId, admin } to req.auth when present.
   */
  async function authGuard(req, res, next) {
    try {
      if (!requireAuth) {
        // Unauthenticated compatibility mode: still allow the route to proceed
        // without an identity; downstream owner checks become 403/404.
        req.auth = null;
        return next();
      }
      const ctx = await authenticate(pool, req.headers.authorization, verifierOptions || {});
      req.auth = ctx;
      return next();
    } catch (err) {
      return next(toHttpError(err));
    }
  }

  /** Convert any typed service error to { status, body }. */
  function toHttpError(err) {
    if (err instanceof AuthError) return withStatus(err, err.status || 401);
    if (err instanceof GameError) return withStatus(err, err.status || 500);
    if (err instanceof QuestionError) return withStatus(err, err.status || 400);
    if (err instanceof UserError) return withStatus(err, err.status || 400);
    return withStatus(err, (err && typeof err.status === 'number') ? err.status : 500);
  }

  function withStatus(err, status) {
    const e = err instanceof Error ? err : new Error(String(err));
    e._status = status;
    return e;
  }

  /** Central error handler that maps status-carrying errors to JSON. */
  function errorHandler(err, _req, res, _next) {
    const status =
      (err && (err._status || err.status)) &&
      Number.isInteger(err._status || err.status)
        ? err._status || err.status
        : 500;
    res.status(status).json({
      error: (err && err.message) || 'Internal server error',
    });
  }

  /**
   * Wrap an async route to forward rejections to the error handler and attach
   * the verified identity (from authGuard) to the handler via req.auth.
   */
  function route(fn) {
    return (req, res, next) => {
      Promise.resolve(fn(req, res))
        .catch((err) => next(toHttpError(err)));
    };
  }

  // -------------------------------------------------------------------------
  // Health + metrics (unauthenticated, per contract).
  // -------------------------------------------------------------------------
  app.get('/health', (_req, res) => {
    res.status(200).json({ status: 'ok' });
  });

  app.get('/metrics', async (_req, res) => {
    if (metrics && typeof metrics.metrics === 'function') {
      res.set('Content-Type', metrics.contentType ? metrics.contentType : 'text/plain');
      return res.status(200).send(await metrics.metrics());
    }
    // No registry configured: still return 200 with an empty metric exposition
    // so the endpoint is real (never a placeholder string body).
    res.set('Content-Type', 'text/plain; version=0.0.4');
    return res.status(200).send('');
  });

  // -------------------------------------------------------------------------
  // Original backward-compatible play entrypoint.
  // -------------------------------------------------------------------------
  app.get('/play', authGuard, route(async (req, res) => {
    const userId = req.auth ? req.auth.userId : null;
    if (userId == null) {
      const err = new AuthError('Authentication required', 401);
      return res.status(401).json({ error: err.message });
    }
    const game = await gameService.newGame(userId, undefined);
    // Original contract: 200 { gameId: integer }.
    return res.status(200).json({ gameId: game.id });
  }));

  // -------------------------------------------------------------------------
  // Game endpoints.
  // -------------------------------------------------------------------------
  app.post('/api/games', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    const questionIds = Array.isArray(body.questionIds) ? body.questionIds : undefined;
    const game = await gameService.newGame(userId, questionIds);
    return res.status(201).json(game);
  }));

  app.get('/api/games/:id', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const game = await gameService.viewGame(parseId(req.params.id), userId);
    return res.status(200).json(game);
  }));

  app.post('/api/games/:id/pause', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.pauseGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/resume', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.resumeGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/answers', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    if (body.questionId == null || body.answer == null) {
      const err = new Error('questionId and answer are required');
      err.status = 400;
      throw err;
    }
    const result = await gameService.answer(
      parseId(req.params.id),
      parseId(body.questionId),
      String(body.answer),
      userId
    );
    return res.status(200).json(result);
  }));

  app.get('/api/games/:id/score', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.viewScore(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  // -------------------------------------------------------------------------
  // Question + admin endpoints.
  // -------------------------------------------------------------------------
  app.get('/api/questions/search', authGuard, route(async (req, res) => {
    const q = typeof req.query.q === 'string' ? req.query.q : '';
    const matched = await questionService.searchQuestions(q);
    return res.status(200).json({ matched });
  }));

  app.post('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const created = await adminService.createQuestion(req.auth.payload, req.body || {});
    return res.status(201).json(created);
  }));

  app.get('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const result = await adminService.listQuestions(req.auth.payload);
    return res.status(200).json(result);
  }));

  app.delete('/api/admin/questions/:id', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const deleted = await adminService.deleteQuestion(req.auth.payload, parseId(req.params.id));
    return res.status(deleted ? 200 : 404).json(deleted ? {} : { error: 'Question not found' });
  }));

  // -------------------------------------------------------------------------
  // Static browser UI at /.
  // -------------------------------------------------------------------------
  const publicDir = path.join(__dirname, '..', 'public');
  app.use(express.static(publicDir));
  app.get('/', (_req, res) => {
    res.sendFile(path.join(publicDir, 'index.html'), (err) => {
      if (err) res.status(404).send('Not found');
    });
  });

  app.use(errorHandler);

  return app;
}

/** Enforce that an identity was resolved; throws 403 if auth was bypassed. */
function requireAuthContext(req) {
  if (!req.auth) {
    const err = new AuthError('Authentication required', 401);
    err._status = 401;
    throw err;
  }
  return req.auth;
}

function requireUserId(req) {
  requireAuthContext(req);
  return req.auth.userId;
}

/** Parse a positive integer path/body id, else throw a 400-typed error. */
function parseId(value) {
  const n = Number(value);
  if (!Number.isInteger(n) || n <= 0) {
    const err = new Error('Invalid id');
    err.status = 400;
    throw err;
  }
  return n;
}

module.exports = {
  createApp,
};

